insert into faqs (question, answer, category) values ('Define credit transfer.', 'Supports credit transfer applications with transcript matching, review, justification, and decision steps.', 'Features');
insert into faqs (question, answer, category) values ('What does the platform type mean?', 'A responsive, web-based Quality Management System accessible from desktop and mobile browsers.', 'System Overview');
insert into faqs (question, answer, category) values ('Where is learning quality data stored?', 'In clo_attainments, cqi_reports, and qs1_papers.', 'Database');
insert into faqs (question, answer, category) values ('What is the timetable feature?', 'Displays teaching schedule and timetable information for students, lecturers, and HOPs.', 'Features');
insert into faqs (question, answer, category) values ('Who can see UNIMY QMS RISE?', 'Used by students, lecturers, Heads of Programme (HOPs), Deans, quality-assurance personnel, and administrators across So-CSI - the School of CyberSecurity and Data Intelligence.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain transcript and PDF OCR extraction.', 'Reduces manual retyping and supports faster preliminary transcript review.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does role-aware access provide?', 'It uses role-based navigation and database access controls to protect student, staff, and institutional information.', 'System Overview');
insert into faqs (question, answer, category) values ('What benefit does preparing course files before teaching provide?', 'Evidence processes must be ready before teaching begins.', 'Procedures');
insert into faqs (question, answer, category) values ('What is the purpose of mobile-responsive design?', 'QMS access must work where users are, including on phones used for attendance and quick academic checks.', 'Justification');
insert into faqs (question, answer, category) values ('What benefit does backups and change control provide?', 'Regular backups and pre-deployment inspection enable recovery and reduce disruption when changes fail.', 'Security');
insert into faqs (question, answer, category) values ('Explain internal audits.', 'Records and manages internal audit activity.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does password protection provide?', 'Passwords, hashes, service-role keys, and private secrets must never be exposed in browser code.', 'Security');
insert into faqs (question, answer, category) values ('Why do we need students see only their own data?', 'Role-based access ensures students see their own permitted information without exposing staff or school-level records.', 'User Roles');
insert into faqs (question, answer, category) values ('Define UNIMY QMS RISE.', 'UNIMY QMS RISE is the University Malaysia of Computer Science & Engineering''s Quality Management System with gamification. It tracks attendance, evaluations, quizzes, and bonuses across all programmes.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the quality cycle stages?', 'Plan, Deliver, Capture Evidence, Measure, Review, Improve, Report. Quality is a repeating process, not a single event.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('How does internal audits work work?', 'They systematically check process effectiveness and evidence completeness to support quality review and accreditation readiness.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What does the Quiz Battle Arena mean?', 'Supports quiz attempts, quiz results, topics, and performance history.', 'Features');
insert into faqs (question, answer, category) values ('What does the Dean role mean?', 'The Dean leads academic quality for So-CSI: school and programme monitoring, quality review, CQI oversight, audit visibility, staff and lecturer review, and strategic reporting.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the purpose of centralising academic operations?', 'It reduces duplicate work, lost files, and dependence on disconnected tools. Every record lives in one workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain the faqs table.', 'Stores frequently asked questions and answers used by the self-service help and AI assistant features.', 'Database');
insert into faqs (question, answer, category) values ('Why do we need centralising academic operations?', 'It reduces duplicate work, lost files, and dependence on disconnected tools. Every record lives in one workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Define the important security rule.', 'The browser application must use only safe public config values. Secret service-role keys must never appear in client-side HTML or JavaScript.', 'Security');
insert into faqs (question, answer, category) values ('Explain academic term management.', 'Defines academic terms and periods used by planning and reporting tools.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about Supabase.', 'The backend platform providing PostgreSQL database and related application services.', 'Terminology');
insert into faqs (question, answer, category) values ('What does the CQI workflow mean?', 'A concern is documented in a CQI report with context, affected programme or course, issue, proposed action, owner, target date, and required evidence. It is reviewed, implemented, evidenced, and closed only when authorised.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the application layer.', 'The main JavaScript application, feature modules, role-aware routing, validation, and dynamic rendering. It coordinates user workflows.', 'Architecture');
insert into faqs (question, answer, category) values ('Justify password protection.', 'Passwords, hashes, service-role keys, and private secrets must never be exposed in browser code.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about messages.', 'Supports internal messages and communication.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does a role-based interface provide?', 'Users should not need to navigate through unrelated or confidential institutional functions.', 'Justification');
insert into faqs (question, answer, category) values ('What does CQI reports mean?', 'Creates, reviews, tracks, and follows up Continuous Quality Improvement actions.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of Row Level Security?', 'It enforces database-level policies that limit records available to each user.', 'Security');
insert into faqs (question, answer, category) values ('Which roles have access to approves CQI closure?', 'The appropriate academic authority - typically the Dean, HOP, or quality reviewer who owns the affected programme or course.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Why do we need active-session handling?', 'Monitoring active session identifiers helps reduce simultaneous or unauthorised account use.', 'Security');
insert into faqs (question, answer, category) values ('Define the QMS abbreviation.', 'QMS stands for Quality Management System - a platform or method used to plan, monitor, evidence, review, and improve quality.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify a central database.', 'Academic quality cannot be managed reliably when critical evidence is spread across personal devices, email, paper, and disconnected spreadsheets.', 'Justification');
insert into faqs (question, answer, category) values ('What is the student dashboard?', 'Student-focused academic shortcuts, activities, points, progress information, and notices.', 'Features');
insert into faqs (question, answer, category) values ('Explain peer chat.', 'Supports student chat requests, approval, rejection, messages, read status, and block controls.', 'Features');
insert into faqs (question, answer, category) values ('Justify quality personnel benefit.', 'Access to course evidence, CLO data, CQI records, audit records, reports, and documents.', 'Benefits');
insert into faqs (question, answer, category) values ('Why is least privilege important?', 'Giving only the minimum access necessary limits damage from mistakes or compromised accounts.', 'Security');
insert into faqs (question, answer, category) values ('Define least privilege.', 'The security principle of giving each user only the access they need.', 'Terminology');
insert into faqs (question, answer, category) values ('Why do we need strengthening student support?', 'It provides study planning, timetable, attendance, messages, quizzes, support tools, and profile functions to help students manage their academic journey.', 'System Overview');
insert into faqs (question, answer, category) values ('What is least privilege?', 'The security principle of giving each user only the access they need.', 'Terminology');
insert into faqs (question, answer, category) values ('Define RLS.', 'Row Level Security - database rules that control which database rows a user can read or change.', 'Terminology');
insert into faqs (question, answer, category) values ('What does RLS mean?', 'Row Level Security - database rules that control which database rows a user can read or change.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain the Staff role.', 'Staff carry out assigned operational or support work. Access varies by assigned role and approved permission.', 'User Roles');
insert into faqs (question, answer, category) values ('What does the QMS abbreviation mean?', 'QMS stands for Quality Management System - a platform or method used to plan, monitor, evidence, review, and improve quality.', 'System Overview');
insert into faqs (question, answer, category) values ('What does the course catalogue mean?', 'Stores subject code, subject name, type, study level, credit hour, prerequisites, grading method, pass criteria, status, semester, and academic year.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of continuous improvement?', 'It records quality observations and CQI follow-up activity to ensure identified issues lead to accountable action.', 'System Overview');
insert into faqs (question, answer, category) values ('What is an attendance session?', 'A controlled attendance event created for a class with a code, time limit, subject, and issuer.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain the clo_attainments table.', 'Stores Course Learning Outcome attainment data linking assessment evidence to intended outcomes.', 'Database');
insert into faqs (question, answer, category) values ('Explain QS1 papers.', 'Supports records connected to quality-system or assessment-paper processes.', 'Features');
insert into faqs (question, answer, category) values ('What is user profile management?', 'View and update permitted personal data, profile avatar, account details, and preferences.', 'Features');
insert into faqs (question, answer, category) values ('What does the data layer mean?', 'Supabase and PostgreSQL database tables, storage, database functions, and policies. It stores academic, user, quality, and service records.', 'Architecture');
insert into faqs (question, answer, category) values ('What is questions the Dean dashboard answers?', 'Which programmes need attention? Are course files and quality evidence complete? What CLO attainment patterns need discussion? Which CQI actions remain pending? What audit observations need follow-up?', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain course prerequisites.', 'Records prerequisite requirements for courses.', 'Features');
insert into faqs (question, answer, category) values ('Why is the objectives of QMS RISE important?', 'To centralise academic operations, support So-CSI governance, improve evidence readiness, strengthen student support, support continuous improvement, improve monitoring, and provide secure role-aware access.', 'System Overview');
