insert into faqs (question, answer, category) values ('What benefit does security and RLS provide?', 'Personal, academic, and institutional data requires access controls at both interface and database levels.', 'Justification');
insert into faqs (question, answer, category) values ('What is the Dean role?', 'The Dean leads academic quality for So-CSI: school and programme monitoring, quality review, CQI oversight, audit visibility, staff and lecturer review, and strategic reporting.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about notification preferences.', 'Stores user communication preferences.', 'Features');
insert into faqs (question, answer, category) values ('What does evidence in QMS context mean?', 'A document, result, record, log, or file that supports a statement or decision.', 'Terminology');
