insert into faqs (question, answer, category) values ('Justify Row Level Security.', 'It enforces database-level policies that limit records available to each user.', 'Security');
insert into faqs (question, answer, category) values ('What is the study plan feature?', 'Builds or displays planned study pathways across semesters.', 'Features');
insert into faqs (question, answer, category) values ('What does CQI mean?', 'Continuous Quality Improvement - a formal process for identifying issues, taking action, and checking results.', 'Terminology');
