insert into faqs (question, answer, category) values ('Explain how internal audits work works.', 'They systematically check process effectiveness and evidence completeness to support quality review and accreditation readiness.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Why is administrators benefit important?', 'Centralised records, role-aware operations, database-backed workflows, and controlled administrative capabilities.', 'Benefits');
insert into faqs (question, answer, category) values ('Why is UNIMY QMS RISE important?', 'It centralises academic quality work - attendance, evidence, evaluation, CLO attainment, CQI, audits, and reporting - replacing disconnected spreadsheets, folders, chats, and emails.', 'System Overview');
insert into faqs (question, answer, category) values ('What is secure login?', 'Student and staff login, session handling, logout, active-device session controls, and password workflows. It confirms identity before showing protected information.', 'Features');
insert into faqs (question, answer, category) values ('Define QS1 papers.', 'Supports records connected to quality-system or assessment-paper processes.', 'Features');
insert into faqs (question, answer, category) values ('Justify administrators benefit.', 'Centralised records, role-aware operations, database-backed workflows, and controlled administrative capabilities.', 'Benefits');
insert into faqs (question, answer, category) values ('What is the course catalogue?', 'Stores subject code, subject name, type, study level, credit hour, prerequisites, grading method, pass criteria, status, semester, and academic year.', 'Features');
insert into faqs (question, answer, category) values ('What does the integration layer mean?', 'QR scanner, camera features, face-auth module, charts, PDF, OCR, and spreadsheet tools. It extends system functions beyond normal forms.', 'Architecture');
insert into faqs (question, answer, category) values ('Explain the data layer.', 'Supabase and PostgreSQL database tables, storage, database functions, and policies. It stores academic, user, quality, and service records.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the attendance_sessions table.', 'Stores controlled attendance events with a code, subject, location, points, expiry, issuer, and active status.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about certificate review.', 'Supports review of submitted certificate evidence, including analysis workflow.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about lecturer and staff management.', 'Maintains staff identity, school, programme, role, title, account state, and authorised permissions.', 'Features');
insert into faqs (question, answer, category) values ('Explain lecturer evaluation.', 'Stores or supports review of lecturer evaluation data.', 'Features');
insert into faqs (question, answer, category) values ('Define the end-of-semester checklist.', 'Record or validate CLO attainment, review evaluation and performance indicators, review course files and audit readiness, create CQI reports, collect evidence, generate reports, and carry approved improvements into the next cycle.', 'Procedures');
insert into faqs (question, answer, category) values ('What does live presence mean?', 'Supports online presence awareness for selected interaction features.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about So-CSI school and programme mapping.', 'Associates staff and students with So-CSI and relevant programmes.', 'Features');
insert into faqs (question, answer, category) values ('Justify centralising academic operations.', 'It reduces duplicate work, lost files, and dependence on disconnected tools. Every record lives in one workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain the integration layer.', 'QR scanner, camera features, face-auth module, charts, PDF, OCR, and spreadsheet tools. It extends system functions beyond normal forms.', 'Architecture');
insert into faqs (question, answer, category) values ('Which tables contain communication and support data?', 'In messages, notification_preferences, faqs, and complaints.', 'Database');
insert into faqs (question, answer, category) values ('Why do we need quality personnel benefit?', 'Access to course evidence, CLO data, CQI records, audit records, reports, and documents.', 'Benefits');
insert into faqs (question, answer, category) values ('Define internal audits.', 'Records and manages internal audit activity.', 'Features');
insert into faqs (question, answer, category) values ('Where does feedback and staff performance data live in the database?', 'In evaluations, lecturer_evaluations, and lecturer_kpi.', 'Database');
insert into faqs (question, answer, category) values ('Who uses can raise a CQI concern?', 'A lecturer, HOP, reviewer, audit team, or Dean can identify and document a concern in a CQI report.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define certificate review.', 'Supports review of submitted certificate evidence, including analysis workflow.', 'Features');
insert into faqs (question, answer, category) values ('Explain the QMS abbreviation.', 'QMS stands for Quality Management System - a platform or method used to plan, monitor, evidence, review, and improve quality.', 'System Overview');
insert into faqs (question, answer, category) values ('What is a HOP?', 'Head of Programme - the person coordinating programme-level academic delivery and quality.', 'Terminology');
insert into faqs (question, answer, category) values ('What is reporting and export?', 'Produces printable, PDF-capable, and spreadsheet-compatible views.', 'Features');
insert into faqs (question, answer, category) values ('Who is responsible for UNIMY QMS RISE?', 'Used by students, lecturers, Heads of Programme (HOPs), Deans, quality-assurance personnel, and administrators across So-CSI - the School of CyberSecurity and Data Intelligence.', 'System Overview');
insert into faqs (question, answer, category) values ('Why do we need password protection?', 'Passwords, hashes, service-role keys, and private secrets must never be exposed in browser code.', 'Security');
insert into faqs (question, answer, category) values ('Why is responsive design matters important?', 'Students, lecturers, and leaders access the system from phones, tablets, laptops, and desktops - the QMS must work everywhere.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the purpose of UNIMY QMS RISE?', 'It centralises academic quality work - attendance, evidence, evaluation, CLO attainment, CQI, audits, and reporting - replacing disconnected spreadsheets, folders, chats, and emails.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify students see only their own data.', 'Role-based access ensures students see their own permitted information without exposing staff or school-level records.', 'User Roles');
insert into faqs (question, answer, category) values ('What benefit does evidence readiness provide?', 'It supports course files, documents, attendance logs, evaluations, audits, and CQI records to create traceable evidence for review, accreditation, and decision-making.', 'System Overview');
insert into faqs (question, answer, category) values ('What is QR attendance session creation?', 'Creates attendance sessions with code, subject, location, points, expiry, issuer, and active status.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need CQI is important?', 'It creates a visible link: observed issue, decision, assigned action, evidence of implementation, review of result.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain an attendance session.', 'A controlled attendance event created for a class with a code, time limit, subject, and issuer.', 'Terminology');
insert into faqs (question, answer, category) values ('What does the course file register mean?', 'Registers and manages course-related evidence or files.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does Deans see school-level data provide?', 'Deans need school-level information to lead academic quality across all So-CSI programmes.', 'User Roles');
insert into faqs (question, answer, category) values ('What data store holds feedback and staff performance data?', 'In evaluations, lecturer_evaluations, and lecturer_kpi.', 'Database');
insert into faqs (question, answer, category) values ('What is transcript and PDF OCR extraction?', 'Reduces manual retyping and supports faster preliminary transcript review.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about So-CSI.', 'So-CSI stands for School of CyberSecurity and Data Intelligence. It is the academic school context for the QMS RISE system.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the process for to validate mobile workflows?', 'Test all major workflows on a phone after UI changes, especially navigation, modals, forms, tables, camera use, and document uploads.', 'Security');
insert into faqs (question, answer, category) values ('What is the Student role?', 'Students participate in learning and manage permitted academic activities: dashboard, timetable, attendance, study plan, quizzes, documents, messages, peer chat, profile, evaluations, complaints, events, and academic support.', 'User Roles');
insert into faqs (question, answer, category) values ('Define the current version.', 'QMS RISE - So-CSI v27.0 Web Application.', 'System Overview');
insert into faqs (question, answer, category) values ('Why is students benefit important?', 'Timetable access, attendance visibility, study planning, quizzes, messages, peer support, documents, events, recognition, and support tools.', 'Benefits');
insert into faqs (question, answer, category) values ('What data store holds attendance data?', 'In attendance, attendance_sessions, and attendance_logs.', 'Database');
insert into faqs (question, answer, category) values ('Why do we need continuous improvement?', 'It records quality observations and CQI follow-up activity to ensure identified issues lead to accountable action.', 'System Overview');
insert into faqs (question, answer, category) values ('Define transcript and PDF OCR extraction.', 'Reduces manual retyping and supports faster preliminary transcript review.', 'Features');
insert into faqs (question, answer, category) values ('Who can see can raise a CQI concern?', 'A lecturer, HOP, reviewer, audit team, or Dean can identify and document a concern in a CQI report.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain the vision of QMS RISE.', 'To make academic quality work visible, structured, traceable, and easier to improve through a common workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the QMS abbreviation?', 'QMS stands for Quality Management System - a platform or method used to plan, monitor, evidence, review, and improve quality.', 'System Overview');
insert into faqs (question, answer, category) values ('What is lecturer evaluation?', 'Stores or supports review of lecturer evaluation data.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the HOP role.', 'Heads of Programme coordinate programme delivery and quality: programme monitoring, academic support, reports, review of course and evidence activity, study-plan support, and approved quality workflows.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about the question bank.', 'Maintains reusable assessment questions and related course information.', 'Features');
insert into faqs (question, answer, category) values ('What database tables support attendance data?', 'In attendance, attendance_sessions, and attendance_logs.', 'Database');
insert into faqs (question, answer, category) values ('What is CLO attainment?', 'Records Course Learning Outcome achievement data.', 'Features');
insert into faqs (question, answer, category) values ('What is document management?', 'Uploads, retrieves, organises, and reviews documents.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need HOPs benefit?', 'Programme-level visibility, course coordination, quality follow-up, study planning, and support workflows.', 'Benefits');
insert into faqs (question, answer, category) values ('Why do we need security and RLS?', 'Personal, academic, and institutional data requires access controls at both interface and database levels.', 'Justification');
insert into faqs (question, answer, category) values ('What is the purpose of active-session handling?', 'Monitoring active session identifiers helps reduce simultaneous or unauthorised account use.', 'Security');
insert into faqs (question, answer, category) values ('Explain the study plan feature.', 'Builds or displays planned study pathways across semesters.', 'Features');
insert into faqs (question, answer, category) values ('Why is the school to programme to course structure important?', 'Quality responsibility needs to be visible at the appropriate level, especially within So-CSI.', 'Justification');
insert into faqs (question, answer, category) values ('Define the quality cycle stages.', 'Plan, Deliver, Capture Evidence, Measure, Review, Improve, Report. Quality is a repeating process, not a single event.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What database tables support documents and course evidence?', 'In documents and course_files.', 'Database');
insert into faqs (question, answer, category) values ('What benefit does HOPs benefit provide?', 'Programme-level visibility, course coordination, quality follow-up, study planning, and support workflows.', 'Benefits');
insert into faqs (question, answer, category) values ('Tell me about attendance bonus tracking.', 'Supports point-based recognition connected to attendance activity.', 'Features');
insert into faqs (question, answer, category) values ('What is the process for internal audits work?', 'They systematically check process effectiveness and evidence completeness to support quality review and accreditation readiness.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Where does peer interaction data live in the database?', 'In peer_chat_requests, peer_chat_messages, and peer_chat_blocks.', 'Database');
insert into faqs (question, answer, category) values ('What does So-CSI mean?', 'So-CSI stands for School of CyberSecurity and Data Intelligence. It is the academic school context for the QMS RISE system.', 'System Overview');
insert into faqs (question, answer, category) values ('Define attendance records.', 'Stores attendance events, student identity, subject, location, type, points, and timestamp.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about a KPI.', 'Key Performance Indicator - a measurable value used to assess performance or progress.', 'Terminology');
insert into faqs (question, answer, category) values ('Which tables contain study planning data?', 'In semester_plans, sp_courses, sp_semester_buckets, sp_student_courses, sp_students, and sp_timetable.', 'Database');
insert into faqs (question, answer, category) values ('What benefit does HOPs see programme-relevant data provide?', 'HOPs need programme-level visibility to coordinate and monitor delivery.', 'User Roles');
insert into faqs (question, answer, category) values ('Why do we need a central database?', 'Academic quality cannot be managed reliably when critical evidence is spread across personal devices, email, paper, and disconnected spreadsheets.', 'Justification');
insert into faqs (question, answer, category) values ('What is an audit trail?', 'A traceable record of actions, dates, decisions, and responsible people.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about the vision of QMS RISE.', 'To make academic quality work visible, structured, traceable, and easier to improve through a common workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Where does audit and compliance data live in the database?', 'In internal_audits and mock_audits.', 'Database');
insert into faqs (question, answer, category) values ('What does the clo_attainments table mean?', 'Stores Course Learning Outcome attainment data linking assessment evidence to intended outcomes.', 'Database');
insert into faqs (question, answer, category) values ('Define document management.', 'Uploads, retrieves, organises, and reviews documents.', 'Features');
insert into faqs (question, answer, category) values ('What is credit transfer?', 'Supports credit transfer applications with transcript matching, review, justification, and decision steps.', 'Features');
insert into faqs (question, answer, category) values ('What is FAQ and self-service help?', 'Provides frequently asked questions and guided support information for all users.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of students benefit?', 'Timetable access, attendance visibility, study planning, quizzes, messages, peer support, documents, events, recognition, and support tools.', 'Benefits');
insert into faqs (question, answer, category) values ('Define CQI.', 'Continuous Quality Improvement - a formal process for identifying issues, taking action, and checking results.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain the during-semester checklist.', 'Create attendance sessions, review attendance patterns, maintain course files, use quizzes and support tools, record quality concerns, and review programme indicators.', 'Procedures');
insert into faqs (question, answer, category) values ('What is CQI?', 'Continuous Quality Improvement - a formal process for identifying issues, taking action, and checking results.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain the timetable feature.', 'Displays teaching schedule and timetable information for students, lecturers, and HOPs.', 'Features');
insert into faqs (question, answer, category) values ('What does internal audits mean?', 'Records and manages internal audit activity.', 'Features');
insert into faqs (question, answer, category) values ('What does the staff table mean?', 'Stores staff profile, school, programme, role, title, active status, and session fields.', 'Database');
insert into faqs (question, answer, category) values ('What is an academic year?', 'The institutional year covering teaching, assessment, and reporting periods.', 'Terminology');
insert into faqs (question, answer, category) values ('Why do we need lecturers benefit?', 'Attendance generation, evidence management, question bank, evaluation support, documents, course-file tools, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('Justify backups and change control.', 'Regular backups and pre-deployment inspection enable recovery and reduce disruption when changes fail.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about the end-of-semester checklist.', 'Record or validate CLO attainment, review evaluation and performance indicators, review course files and audit readiness, create CQI reports, collect evidence, generate reports, and carry approved improvements into the next cycle.', 'Procedures');
insert into faqs (question, answer, category) values ('What does the backend platform mean?', 'Supabase - providing PostgreSQL database, storage, and related application services.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the purpose of strengthening student support?', 'It provides study planning, timetable, attendance, messages, quizzes, support tools, and profile functions to help students manage their academic journey.', 'System Overview');
insert into faqs (question, answer, category) values ('How does CQI actions are closed work?', 'The record is closed only when an authorised reviewer accepts the evidence that the action has been implemented and was effective.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about badges and certificates.', 'Records badges, student badges, and certificates.', 'Features');
insert into faqs (question, answer, category) values ('Explain certificate review.', 'Supports review of submitted certificate evidence, including analysis workflow.', 'Features');
insert into faqs (question, answer, category) values ('Describe the QMS adapts to mobile screens.', 'Large grids collapse to one or two columns, navigation moves to a hamburger menu, and UI elements stay inside the main screen frame.', 'Architecture');
insert into faqs (question, answer, category) values ('Which tables contain course catalogue data?', 'In the courses, course_prerequisites, and academic_terms tables.', 'Database');
insert into faqs (question, answer, category) values ('Justify continuous improvement.', 'It records quality observations and CQI follow-up activity to ensure identified issues lead to accountable action.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the Student role.', 'Students participate in learning and manage permitted academic activities: dashboard, timetable, attendance, study plan, quizzes, documents, messages, peer chat, profile, evaluations, complaints, events, and academic support.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the question bank?', 'Maintains reusable assessment questions and related course information.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need mobile-responsive design?', 'QMS access must work where users are, including on phones used for attendance and quick academic checks.', 'Justification');
insert into faqs (question, answer, category) values ('What is the cqi_reports table?', 'Stores Continuous Quality Improvement actions with context, affected programme or course, issue description, proposed action, owner, target date, and required evidence.', 'Database');
insert into faqs (question, answer, category) values ('What does the Staff role mean?', 'Staff carry out assigned operational or support work. Access varies by assigned role and approved permission.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain the deployment layer.', 'Web hosting and HTTPS deployment configuration. It delivers the QMS to users through a browser.', 'Architecture');
insert into faqs (question, answer, category) values ('How does to validate mobile workflows work?', 'Test all major workflows on a phone after UI changes, especially navigation, modals, forms, tables, camera use, and document uploads.', 'Security');
insert into faqs (question, answer, category) values ('Justify HOPs benefit.', 'Programme-level visibility, course coordination, quality follow-up, study planning, and support workflows.', 'Benefits');
insert into faqs (question, answer, category) values ('What is the access and session layer?', 'Authentication, user roles, active-session controls, and Row Level Security policies. It identifies users and limits access.', 'Architecture');
insert into faqs (question, answer, category) values ('Define QR attendance.', 'Attendance recorded by scanning a QR code tied to an active attendance session.', 'Terminology');
insert into faqs (question, answer, category) values ('How does mock audits work work?', 'They simulate formal audit activity to find evidence gaps early and reduce avoidable audit risk.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the application layer?', 'The main JavaScript application, feature modules, role-aware routing, validation, and dynamic rendering. It coordinates user workflows.', 'Architecture');
insert into faqs (question, answer, category) values ('What does QS1 papers mean?', 'Supports records connected to quality-system or assessment-paper processes.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does CQI is important provide?', 'It creates a visible link: observed issue, decision, assigned action, evidence of implementation, review of result.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define evaluations.', 'Supports submission and review of evaluation-related records.', 'Features');
insert into faqs (question, answer, category) values ('Explain the start-of-semester checklist.', 'Confirm academic term and year, verify course catalogue, confirm staff role and student status, review timetable, prepare course files, and test login and role-specific navigation.', 'Procedures');
insert into faqs (question, answer, category) values ('Why is security and RLS important?', 'Personal, academic, and institutional data requires access controls at both interface and database levels.', 'Justification');
insert into faqs (question, answer, category) values ('What does enrolment requests mean?', 'Captures and tracks requests related to enrolment or registration.', 'Features');
insert into faqs (question, answer, category) values ('Define a HOP.', 'Head of Programme - the person coordinating programme-level academic delivery and quality.', 'Terminology');
insert into faqs (question, answer, category) values ('Why do we need the objectives of QMS RISE?', 'To centralise academic operations, support So-CSI governance, improve evidence readiness, strengthen student support, support continuous improvement, improve monitoring, and provide secure role-aware access.', 'System Overview');
insert into faqs (question, answer, category) values ('What benefit does a central database provide?', 'Academic quality cannot be managed reliably when critical evidence is spread across personal devices, email, paper, and disconnected spreadsheets.', 'Justification');
insert into faqs (question, answer, category) values ('Explain the staff table.', 'Stores staff profile, school, programme, role, title, active status, and session fields.', 'Database');
insert into faqs (question, answer, category) values ('What does events and bookings mean?', 'Supports events, event bookings, and staff visibility of participation.', 'Features');
insert into faqs (question, answer, category) values ('What does the institutional hierarchy mean?', 'So-CSI (School) contains programmes; programmes contain courses; courses involve lecturers, students, attendance, assessments, and evidence.', 'System Overview');
insert into faqs (question, answer, category) values ('Why do we need document controls?', 'Limiting document access by role and purpose protects course, staff, student, and audit evidence.', 'Security');
insert into faqs (question, answer, category) values ('Define face authentication.', 'Uses camera and face-related workflows where enabled and approved.', 'Features');
insert into faqs (question, answer, category) values ('What does the Lecturer role mean?', 'Lecturers deliver teaching, manage course-related evidence, and support students: attendance generation, course files, question bank, document tools, evaluation activity, academic support, and assigned reports.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the purpose of students see only their own data?', 'Role-based access ensures students see their own permitted information without exposing staff or school-level records.', 'User Roles');
insert into faqs (question, answer, category) values ('Define the attendance_logs table.', 'Stores individual attendance check-ins with student identity, subject, location, type, points, and timestamp.', 'Database');
insert into faqs (question, answer, category) values ('Explain the attendance_sessions table.', 'Stores controlled attendance events with a code, subject, location, points, expiry, issuer, and active status.', 'Database');
insert into faqs (question, answer, category) values ('Define the question bank.', 'Maintains reusable assessment questions and related course information.', 'Features');
insert into faqs (question, answer, category) values ('Where does events and services data live in the database?', 'In events, event_bookings, enrolment_requests, and credit_transfers.', 'Database');
insert into faqs (question, answer, category) values ('What does the during-semester checklist mean?', 'Create attendance sessions, review attendance patterns, maintain course files, use quizzes and support tools, record quality concerns, and review programme indicators.', 'Procedures');
insert into faqs (question, answer, category) values ('Why is evidence readiness important?', 'It supports course files, documents, attendance logs, evaluations, audits, and CQI records to create traceable evidence for review, accreditation, and decision-making.', 'System Overview');
insert into faqs (question, answer, category) values ('Define mock audits.', 'Supports readiness reviews before formal audit or accreditation activity.', 'Features');
insert into faqs (question, answer, category) values ('What is CQI reports?', 'Creates, reviews, tracks, and follows up Continuous Quality Improvement actions.', 'Features');
insert into faqs (question, answer, category) values ('Define the HOP role.', 'Heads of Programme coordinate programme delivery and quality: programme monitoring, academic support, reports, review of course and evidence activity, study-plan support, and approved quality workflows.', 'User Roles');
insert into faqs (question, answer, category) values ('Which tables contain feedback and staff performance data?', 'In evaluations, lecturer_evaluations, and lecturer_kpi.', 'Database');
insert into faqs (question, answer, category) values ('Explain the reporting layer.', 'Tables, dashboards, browser print and PDF support, and spreadsheet-capable tools. It converts records into reviewable information.', 'Architecture');
insert into faqs (question, answer, category) values ('Justify secure authentication.', 'It establishes reliable user identity and prevents unauthorised access.', 'Security');
insert into faqs (question, answer, category) values ('Define the study plan feature.', 'Builds or displays planned study pathways across semesters.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about least privilege.', 'The security principle of giving each user only the access they need.', 'Terminology');
insert into faqs (question, answer, category) values ('Why is strengthening student support important?', 'It provides study planning, timetable, attendance, messages, quizzes, support tools, and profile functions to help students manage their academic journey.', 'System Overview');
insert into faqs (question, answer, category) values ('What does mock audits mean?', 'Supports readiness reviews before formal audit or accreditation activity.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need responsive design matters?', 'Students, lecturers, and leaders access the system from phones, tablets, laptops, and desktops - the QMS must work everywhere.', 'Architecture');
insert into faqs (question, answer, category) values ('Walk me through the QMS adapts to mobile screens.', 'Large grids collapse to one or two columns, navigation moves to a hamburger menu, and UI elements stay inside the main screen frame.', 'Architecture');
insert into faqs (question, answer, category) values ('Explain the CQI workflow.', 'A concern is documented in a CQI report with context, affected programme or course, issue, proposed action, owner, target date, and required evidence. It is reviewed, implemented, evidenced, and closed only when authorised.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Describe to validate mobile workflows.', 'Test all major workflows on a phone after UI changes, especially navigation, modals, forms, tables, camera use, and document uploads.', 'Security');
insert into faqs (question, answer, category) values ('Explain FAQ and self-service help.', 'Provides frequently asked questions and guided support information for all users.', 'Features');
insert into faqs (question, answer, category) values ('Explain evaluations.', 'Supports submission and review of evaluation-related records.', 'Features');
insert into faqs (question, answer, category) values ('What does the start-of-semester checklist mean?', 'Confirm academic term and year, verify course catalogue, confirm staff role and student status, review timetable, prepare course files, and test login and role-specific navigation.', 'Procedures');
insert into faqs (question, answer, category) values ('Define the AI assistant interface.', 'Provides an AI-assistant entry point where configured.', 'Features');
insert into faqs (question, answer, category) values ('Explain QR attendance.', 'Attendance recorded by scanning a QR code tied to an active attendance session.', 'Terminology');
insert into faqs (question, answer, category) values ('Who uses the system architect?', 'The system was conceived, developed, and built by R. Vinod Sarna, Dean of So-CSI and HOP for BCY and BDS.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the timetable feature.', 'Displays teaching schedule and timetable information for students, lecturers, and HOPs.', 'Features');
insert into faqs (question, answer, category) values ('Why is mobile-responsive design important?', 'QMS access must work where users are, including on phones used for attendance and quick academic checks.', 'Justification');
insert into faqs (question, answer, category) values ('What does the role-aware dashboard mean?', 'A dashboard and navigation appropriate to the signed-in user role.', 'Features');
insert into faqs (question, answer, category) values ('Explain the end-of-semester checklist.', 'Record or validate CLO attainment, review evaluation and performance indicators, review course files and audit readiness, create CQI reports, collect evidence, generate reports, and carry approved improvements into the next cycle.', 'Procedures');
insert into faqs (question, answer, category) values ('What does the mobile-responsive interface mean?', 'Uses adaptive layout, responsive grid behaviour, mobile navigation, and touch interaction.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about an academic term.', 'A defined teaching period, such as a semester.', 'Terminology');
insert into faqs (question, answer, category) values ('Why do we need the QMS works as a continuous cycle?', 'Quality is a repeating process of Plan, Deliver, Capture Evidence, Measure, Review, Improve, and Report - not a single audit event.', 'System Overview');
insert into faqs (question, answer, category) values ('Which roles have access to the system architect?', 'The system was conceived, developed, and built by R. Vinod Sarna, Dean of So-CSI and HOP for BCY and BDS.', 'System Overview');
insert into faqs (question, answer, category) values ('Where is study planning data stored?', 'In semester_plans, sp_courses, sp_semester_buckets, sp_student_courses, sp_students, and sp_timetable.', 'Database');
insert into faqs (question, answer, category) values ('Explain user profile management.', 'View and update permitted personal data, profile avatar, account details, and preferences.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about enrolment requests.', 'Captures and tracks requests related to enrolment or registration.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about peer chat.', 'Supports student chat requests, approval, rejection, messages, read status, and block controls.', 'Features');
insert into faqs (question, answer, category) values ('Justify UNIMY QMS RISE.', 'It centralises academic quality work - attendance, evidence, evaluation, CLO attainment, CQI, audits, and reporting - replacing disconnected spreadsheets, folders, chats, and emails.', 'System Overview');
insert into faqs (question, answer, category) values ('What does academic support mean?', 'Provides student-support or academic-assistance workflows.', 'Features');
insert into faqs (question, answer, category) values ('Justify role-aware access.', 'It uses role-based navigation and database access controls to protect student, staff, and institutional information.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about face authentication.', 'Uses camera and face-related workflows where enabled and approved.', 'Features');
insert into faqs (question, answer, category) values ('What is the mobile-responsive interface?', 'Uses adaptive layout, responsive grid behaviour, mobile navigation, and touch interaction.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need Row Level Security?', 'It enforces database-level policies that limit records available to each user.', 'Security');
insert into faqs (question, answer, category) values ('Where is assessment engagement data stored?', 'In question_bank, quiz_attempts, and quiz_results.', 'Database');
insert into faqs (question, answer, category) values ('What is the important security rule?', 'The browser application must use only safe public config values. Secret service-role keys must never appear in client-side HTML or JavaScript.', 'Security');
insert into faqs (question, answer, category) values ('Explain how mock audits work works.', 'They simulate formal audit activity to find evidence gaps early and reduce avoidable audit risk.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What benefit does face data governance provide?', 'Face authentication must be used only with formal approval, consent, retention rules, and data-protection safeguards.', 'Security');
insert into faqs (question, answer, category) values ('Justify Deans see school-level data.', 'Deans need school-level information to lead academic quality across all So-CSI programmes.', 'User Roles');
insert into faqs (question, answer, category) values ('What does QR attendance session creation mean?', 'Creates attendance sessions with code, subject, location, points, expiry, issuer, and active status.', 'Features');
insert into faqs (question, answer, category) values ('Explain the institutional hierarchy.', 'So-CSI (School) contains programmes; programmes contain courses; courses involve lecturers, students, attendance, assessments, and evidence.', 'System Overview');
insert into faqs (question, answer, category) values ('What benefit does the QMS works as a continuous cycle provide?', 'Quality is a repeating process of Plan, Deliver, Capture Evidence, Measure, Review, Improve, and Report - not a single audit event.', 'System Overview');
insert into faqs (question, answer, category) values ('Who can see the system architect?', 'The system was conceived, developed, and built by R. Vinod Sarna, Dean of So-CSI and HOP for BCY and BDS.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify face data governance.', 'Face authentication must be used only with formal approval, consent, retention rules, and data-protection safeguards.', 'Security');
insert into faqs (question, answer, category) values ('Explain complaints management.', 'Captures, tracks, and supports resolution of complaints.', 'Features');
insert into faqs (question, answer, category) values ('What is badges and certificates?', 'Records badges, student badges, and certificates.', 'Features');
insert into faqs (question, answer, category) values ('Explain a study plan.', 'A structured plan showing courses across future or current academic terms.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the staff table?', 'Stores staff profile, school, programme, role, title, active status, and session fields.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about the attendance_sessions table.', 'Stores controlled attendance events with a code, subject, location, points, expiry, issuer, and active status.', 'Database');
insert into faqs (question, answer, category) values ('Why is role-aware access important?', 'It uses role-based navigation and database access controls to protect student, staff, and institutional information.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the institutional hierarchy?', 'So-CSI (School) contains programmes; programmes contain courses; courses involve lecturers, students, attendance, assessments, and evidence.', 'System Overview');
insert into faqs (question, answer, category) values ('Define the presentation layer.', 'HTML, CSS, responsive UI, navigation, dashboards, cards, forms, tables, modals, and charts. It shows information and captures user actions.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about the Staff role.', 'Staff carry out assigned operational or support work. Access varies by assigned role and approved permission.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about lecturer evaluation.', 'Stores or supports review of lecturer evaluation data.', 'Features');
insert into faqs (question, answer, category) values ('Where is peer interaction data stored?', 'In peer_chat_requests, peer_chat_messages, and peer_chat_blocks.', 'Database');
insert into faqs (question, answer, category) values ('What is the process for mock audits work?', 'They simulate formal audit activity to find evidence gaps early and reduce avoidable audit risk.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain the cqi_reports table.', 'Stores Continuous Quality Improvement actions with context, affected programme or course, issue description, proposed action, owner, target date, and required evidence.', 'Database');
insert into faqs (question, answer, category) values ('What is live presence?', 'Supports online presence awareness for selected interaction features.', 'Features');
insert into faqs (question, answer, category) values ('What does messages mean?', 'Supports internal messages and communication.', 'Features');
insert into faqs (question, answer, category) values ('Define the start-of-semester checklist.', 'Confirm academic term and year, verify course catalogue, confirm staff role and student status, review timetable, prepare course files, and test login and role-specific navigation.', 'Procedures');
insert into faqs (question, answer, category) values ('Justify a role-based interface.', 'Users should not need to navigate through unrelated or confidential institutional functions.', 'Justification');
insert into faqs (question, answer, category) values ('Tell me about the faqs table.', 'Stores frequently asked questions and answers used by the self-service help and AI assistant features.', 'Database');
insert into faqs (question, answer, category) values ('Explain a dashboard.', 'A visual summary of key information, indicators, status, and shortcuts.', 'Terminology');
insert into faqs (question, answer, category) values ('What does the deployment layer mean?', 'Web hosting and HTTPS deployment configuration. It delivers the QMS to users through a browser.', 'Architecture');
insert into faqs (question, answer, category) values ('Why is auditability important?', 'Useful timestamps, status changes, responsible person details, and evidence references allow decisions to be verified.', 'Security');
insert into faqs (question, answer, category) values ('Explain events and bookings.', 'Supports events, event bookings, and staff visibility of participation.', 'Features');
insert into faqs (question, answer, category) values ('Explain the student dashboard.', 'Student-focused academic shortcuts, activities, points, progress information, and notices.', 'Features');
insert into faqs (question, answer, category) values ('Explain least privilege.', 'The security principle of giving each user only the access they need.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the data layer?', 'Supabase and PostgreSQL database tables, storage, database functions, and policies. It stores academic, user, quality, and service records.', 'Architecture');
insert into faqs (question, answer, category) values ('Why do we need evidence readiness?', 'It supports course files, documents, attendance logs, evaluations, audits, and CQI records to create traceable evidence for review, accreditation, and decision-making.', 'System Overview');
insert into faqs (question, answer, category) values ('What does UNIMY QMS RISE mean?', 'UNIMY QMS RISE is the University Malaysia of Computer Science & Engineering''s Quality Management System with gamification. It tracks attendance, evaluations, quizzes, and bonuses across all programmes.', 'System Overview');
insert into faqs (question, answer, category) values ('What data store holds audit and compliance data?', 'In internal_audits and mock_audits.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about the presentation layer.', 'HTML, CSS, responsive UI, navigation, dashboards, cards, forms, tables, modals, and charts. It shows information and captures user actions.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the course catalogue.', 'Stores subject code, subject name, type, study level, credit hour, prerequisites, grading method, pass criteria, status, semester, and academic year.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of verifying course catalogue details?', 'Course delivery information must be correct before students use it.', 'Procedures');
insert into faqs (question, answer, category) values ('What database tables support peer interaction data?', 'In peer_chat_requests, peer_chat_messages, and peer_chat_blocks.', 'Database');
insert into faqs (question, answer, category) values ('Explain the course file register.', 'Registers and manages course-related evidence or files.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of quiz, points, badges, and certificates?', 'Appropriate engagement features can encourage participation and recognise achievement.', 'Justification');
insert into faqs (question, answer, category) values ('Define course prerequisites.', 'Records prerequisite requirements for courses.', 'Features');
insert into faqs (question, answer, category) values ('Which roles have access to UNIMY QMS RISE?', 'Used by students, lecturers, Heads of Programme (HOPs), Deans, quality-assurance personnel, and administrators across So-CSI - the School of CyberSecurity and Data Intelligence.', 'System Overview');
insert into faqs (question, answer, category) values ('Why is password protection important?', 'Passwords, hashes, service-role keys, and private secrets must never be exposed in browser code.', 'Security');
insert into faqs (question, answer, category) values ('What is the during-semester checklist?', 'Create attendance sessions, review attendance patterns, maintain course files, use quizzes and support tools, record quality concerns, and review programme indicators.', 'Procedures');
insert into faqs (question, answer, category) values ('Tell me about a study plan.', 'A structured plan showing courses across future or current academic terms.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about academic support.', 'Provides student-support or academic-assistance workflows.', 'Features');
insert into faqs (question, answer, category) values ('What does FAQ and self-service help mean?', 'Provides frequently asked questions and guided support information for all users.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the QMS abbreviation.', 'QMS stands for Quality Management System - a platform or method used to plan, monitor, evidence, review, and improve quality.', 'System Overview');
insert into faqs (question, answer, category) values ('What data store holds study planning data?', 'In semester_plans, sp_courses, sp_semester_buckets, sp_student_courses, sp_students, and sp_timetable.', 'Database');
insert into faqs (question, answer, category) values ('What benefit does active-session handling provide?', 'Monitoring active session identifiers helps reduce simultaneous or unauthorised account use.', 'Security');
insert into faqs (question, answer, category) values ('Explain the students table.', 'Stores student profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('What is attendance records?', 'Stores attendance events, student identity, subject, location, type, points, and timestamp.', 'Features');
insert into faqs (question, answer, category) values ('Explain the Administrator role.', 'Administrators maintain authorised system and data operations: database administration tools, selected configuration, and controlled user and role administration.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about QR attendance session creation.', 'Creates attendance sessions with code, subject, location, points, expiry, issuer, and active status.', 'Features');
insert into faqs (question, answer, category) values ('Define Supabase.', 'The backend platform providing PostgreSQL database and related application services.', 'Terminology');
insert into faqs (question, answer, category) values ('Where does learning quality data live in the database?', 'In clo_attainments, cqi_reports, and qs1_papers.', 'Database');
insert into faqs (question, answer, category) values ('What benefit does secure authentication provide?', 'It establishes reliable user identity and prevents unauthorised access.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about an audit trail.', 'A traceable record of actions, dates, decisions, and responsible people.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain document management.', 'Uploads, retrieves, organises, and reviews documents.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the QA and CQI queue.', 'A structured view of quality or improvement items for review.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the reporting layer.', 'Tables, dashboards, browser print and PDF support, and spreadsheet-capable tools. It converts records into reviewable information.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about secure login.', 'Student and staff login, session handling, logout, active-device session controls, and password workflows. It confirms identity before showing protected information.', 'Features');
insert into faqs (question, answer, category) values ('What does certificate review mean?', 'Supports review of submitted certificate evidence, including analysis workflow.', 'Features');
insert into faqs (question, answer, category) values ('Define RISE points and tiers.', 'Allocates and calculates points across attendance, evaluation, quizzes, bonuses, streaks, workshops, competitions, and Coursera activity.', 'Features');
insert into faqs (question, answer, category) values ('What database tables support learning quality data?', 'In clo_attainments, cqi_reports, and qs1_papers.', 'Database');
insert into faqs (question, answer, category) values ('What does a CLO mean?', 'Course Learning Outcome - a measurable statement of what a student should achieve after a course.', 'Terminology');
insert into faqs (question, answer, category) values ('Define So-CSI school and programme mapping.', 'Associates staff and students with So-CSI and relevant programmes.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of the school to programme to course structure?', 'Quality responsibility needs to be visible at the appropriate level, especially within So-CSI.', 'Justification');
insert into faqs (question, answer, category) values ('What is the HOP role?', 'Heads of Programme coordinate programme delivery and quality: programme monitoring, academic support, reports, review of course and evidence activity, study-plan support, and approved quality workflows.', 'User Roles');
insert into faqs (question, answer, category) values ('Define a dashboard.', 'A visual summary of key information, indicators, status, and shortcuts.', 'Terminology');
insert into faqs (question, answer, category) values ('What does CLO attainment mean?', 'Records Course Learning Outcome achievement data.', 'Features');
insert into faqs (question, answer, category) values ('What is a KPI?', 'Key Performance Indicator - a measurable value used to assess performance or progress.', 'Terminology');
insert into faqs (question, answer, category) values ('Where is events and services data stored?', 'In events, event_bookings, enrolment_requests, and credit_transfers.', 'Database');
insert into faqs (question, answer, category) values ('What is So-CSI school and programme mapping?', 'Associates staff and students with So-CSI and relevant programmes.', 'Features');
insert into faqs (question, answer, category) values ('Explain messages.', 'Supports internal messages and communication.', 'Features');
insert into faqs (question, answer, category) values ('What does evaluation reports mean?', 'Presents evaluation-related reports and analysis.', 'Features');
insert into faqs (question, answer, category) values ('Justify reviewing programme and school indicators.', 'HOPs and the Dean can intervene before issues grow.', 'Procedures');
insert into faqs (question, answer, category) values ('What is the end-of-semester checklist?', 'Record or validate CLO attainment, review evaluation and performance indicators, review course files and audit readiness, create CQI reports, collect evidence, generate reports, and carry approved improvements into the next cycle.', 'Procedures');
insert into faqs (question, answer, category) values ('Why do we need quiz, points, badges, and certificates?', 'Appropriate engagement features can encourage participation and recognise achievement.', 'Justification');
insert into faqs (question, answer, category) values ('What does complaints management mean?', 'Captures, tracks, and supports resolution of complaints.', 'Features');
insert into faqs (question, answer, category) values ('What does the AI assistant interface mean?', 'Provides an AI-assistant entry point where configured.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of responsive design matters?', 'Students, lecturers, and leaders access the system from phones, tablets, laptops, and desktops - the QMS must work everywhere.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the course file register.', 'Registers and manages course-related evidence or files.', 'Features');
insert into faqs (question, answer, category) values ('Define notification preferences.', 'Stores user communication preferences.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need students benefit?', 'Timetable access, attendance visibility, study planning, quizzes, messages, peer support, documents, events, recognition, and support tools.', 'Benefits');
insert into faqs (question, answer, category) values ('What is face authentication?', 'Uses camera and face-related workflows where enabled and approved.', 'Features');
insert into faqs (question, answer, category) values ('What database tables support events and services data?', 'In events, event_bookings, enrolment_requests, and credit_transfers.', 'Database');
insert into faqs (question, answer, category) values ('Justify confirming the academic term.', 'It ensures all records use a consistent time reference.', 'Procedures');
insert into faqs (question, answer, category) values ('Define the reporting layer.', 'Tables, dashboards, browser print and PDF support, and spreadsheet-capable tools. It converts records into reviewable information.', 'Architecture');
insert into faqs (question, answer, category) values ('What does an academic year mean?', 'The institutional year covering teaching, assessment, and reporting periods.', 'Terminology');
insert into faqs (question, answer, category) values ('Define evidence in QMS context.', 'A document, result, record, log, or file that supports a statement or decision.', 'Terminology');
insert into faqs (question, answer, category) values ('What is a course file?', 'A structured collection of evidence related to course delivery, assessment, review, and improvement.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about the application layer.', 'The main JavaScript application, feature modules, role-aware routing, validation, and dynamic rendering. It coordinates user workflows.', 'Architecture');
insert into faqs (question, answer, category) values ('Explain how the QMS adapts to mobile screens works.', 'Large grids collapse to one or two columns, navigation moves to a hamburger menu, and UI elements stay inside the main screen frame.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about course prerequisites.', 'Records prerequisite requirements for courses.', 'Features');
insert into faqs (question, answer, category) values ('What does the HOP role mean?', 'Heads of Programme coordinate programme delivery and quality: programme monitoring, academic support, reports, review of course and evidence activity, study-plan support, and approved quality workflows.', 'User Roles');
insert into faqs (question, answer, category) values ('What database tables support communication and support data?', 'In messages, notification_preferences, faqs, and complaints.', 'Database');
insert into faqs (question, answer, category) values ('What user roles interact with UNIMY QMS RISE?', 'Used by students, lecturers, Heads of Programme (HOPs), Deans, quality-assurance personnel, and administrators across So-CSI - the School of CyberSecurity and Data Intelligence.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify role-based access.', 'A QMS stores personal data, attendance, academic evidence, evaluations, complaints, staff records, and reports. Not all users should see all records.', 'User Roles');
insert into faqs (question, answer, category) values ('Why do we need HOPs see programme-relevant data?', 'HOPs need programme-level visibility to coordinate and monitor delivery.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain notification preferences.', 'Stores user communication preferences.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of HOPs see programme-relevant data?', 'HOPs need programme-level visibility to coordinate and monitor delivery.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain the presentation layer.', 'HTML, CSS, responsive UI, navigation, dashboards, cards, forms, tables, modals, and charts. It shows information and captures user actions.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the platform type?', 'A responsive, web-based Quality Management System accessible from desktop and mobile browsers.', 'System Overview');
insert into faqs (question, answer, category) values ('What database tables support recognition and achievement data?', 'In rise_points, badges, student_badges, and certificates.', 'Database');
insert into faqs (question, answer, category) values ('Why is the Dean benefits important?', 'School-level oversight of programmes, evidence, attainment, CQI, audits, staff performance, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('Tell me about CQI.', 'Continuous Quality Improvement - a formal process for identifying issues, taking action, and checking results.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the purpose of backups and change control?', 'Regular backups and pre-deployment inspection enable recovery and reduce disruption when changes fail.', 'Security');
insert into faqs (question, answer, category) values ('Explain evaluation reports.', 'Presents evaluation-related reports and analysis.', 'Features');
insert into faqs (question, answer, category) values ('What is the backend platform?', 'Supabase - providing PostgreSQL database, storage, and related application services.', 'Architecture');
insert into faqs (question, answer, category) values ('Why do we need auditability?', 'Useful timestamps, status changes, responsible person details, and evidence references allow decisions to be verified.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about the Dean role.', 'The Dean leads academic quality for So-CSI: school and programme monitoring, quality review, CQI oversight, audit visibility, staff and lecturer review, and strategic reporting.', 'User Roles');
insert into faqs (question, answer, category) values ('Why do we need face data governance?', 'Face authentication must be used only with formal approval, consent, retention rules, and data-protection safeguards.', 'Security');
insert into faqs (question, answer, category) values ('Define an academic year.', 'The institutional year covering teaching, assessment, and reporting periods.', 'Terminology');
insert into faqs (question, answer, category) values ('What does a HOP mean?', 'Head of Programme - the person coordinating programme-level academic delivery and quality.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the reporting layer?', 'Tables, dashboards, browser print and PDF support, and spreadsheet-capable tools. It converts records into reviewable information.', 'Architecture');
insert into faqs (question, answer, category) values ('What data store holds course catalogue data?', 'In the courses, course_prerequisites, and academic_terms tables.', 'Database');
insert into faqs (question, answer, category) values ('Describe the QA and CQI queue works.', 'It shows pending actions with status, ownership, and follow-up so nothing gets lost between meetings.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the Staff role.', 'Staff carry out assigned operational or support work. Access varies by assigned role and approved permission.', 'User Roles');
insert into faqs (question, answer, category) values ('What data store holds recognition and achievement data?', 'In rise_points, badges, student_badges, and certificates.', 'Database');
insert into faqs (question, answer, category) values ('Which tables contain documents and course evidence?', 'In documents and course_files.', 'Database');
insert into faqs (question, answer, category) values ('What does the QA and CQI queue mean?', 'A structured view of quality or improvement items for review.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of the QMS works as a continuous cycle?', 'Quality is a repeating process of Plan, Deliver, Capture Evidence, Measure, Review, Improve, and Report - not a single audit event.', 'System Overview');
insert into faqs (question, answer, category) values ('What does the students table mean?', 'Stores student profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('What does the presentation layer mean?', 'HTML, CSS, responsive UI, navigation, dashboards, cards, forms, tables, modals, and charts. It shows information and captures user actions.', 'Architecture');
insert into faqs (question, answer, category) values ('What database tables support course catalogue data?', 'In the courses, course_prerequisites, and academic_terms tables.', 'Database');
insert into faqs (question, answer, category) values ('What is the purpose of least privilege?', 'Giving only the minimum access necessary limits damage from mistakes or compromised accounts.', 'Security');
insert into faqs (question, answer, category) values ('What benefit does the objectives of QMS RISE provide?', 'To centralise academic operations, support So-CSI governance, improve evidence readiness, strengthen student support, support continuous improvement, improve monitoring, and provide secure role-aware access.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain evidence in QMS context.', 'A document, result, record, log, or file that supports a statement or decision.', 'Terminology');
insert into faqs (question, answer, category) values ('Who uses approves CQI closure?', 'The appropriate academic authority - typically the Dean, HOP, or quality reviewer who owns the affected programme or course.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Where is communication and support data stored?', 'In messages, notification_preferences, faqs, and complaints.', 'Database');
insert into faqs (question, answer, category) values ('Define peer chat.', 'Supports student chat requests, approval, rejection, messages, read status, and block controls.', 'Features');
insert into faqs (question, answer, category) values ('What is notification preferences?', 'Stores user communication preferences.', 'Features');
insert into faqs (question, answer, category) values ('What does the timetable feature mean?', 'Displays teaching schedule and timetable information for students, lecturers, and HOPs.', 'Features');
insert into faqs (question, answer, category) values ('Justify HOPs see programme-relevant data.', 'HOPs need programme-level visibility to coordinate and monitor delivery.', 'User Roles');
insert into faqs (question, answer, category) values ('What data store holds learning quality data?', 'In clo_attainments, cqi_reports, and qs1_papers.', 'Database');
insert into faqs (question, answer, category) values ('Justify students benefit.', 'Timetable access, attendance visibility, study planning, quizzes, messages, peer support, documents, events, recognition, and support tools.', 'Benefits');
insert into faqs (question, answer, category) values ('What is UNIMY QMS RISE?', 'UNIMY QMS RISE is the University Malaysia of Computer Science & Engineering''s Quality Management System with gamification. It tracks attendance, evaluations, quizzes, and bonuses across all programmes.', 'System Overview');
insert into faqs (question, answer, category) values ('What does notification preferences mean?', 'Stores user communication preferences.', 'Features');
insert into faqs (question, answer, category) values ('What is the vision of QMS RISE?', 'To make academic quality work visible, structured, traceable, and easier to improve through a common workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Walk me through to validate mobile workflows.', 'Test all major workflows on a phone after UI changes, especially navigation, modals, forms, tables, camera use, and document uploads.', 'Security');
insert into faqs (question, answer, category) values ('Explain RISE points and tiers.', 'Allocates and calculates points across attendance, evaluation, quizzes, bonuses, streaks, workshops, competitions, and Coursera activity.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does administrators benefit provide?', 'Centralised records, role-aware operations, database-backed workflows, and controlled administrative capabilities.', 'Benefits');
insert into faqs (question, answer, category) values ('Tell me about the clo_attainments table.', 'Stores Course Learning Outcome attainment data linking assessment evidence to intended outcomes.', 'Database');
insert into faqs (question, answer, category) values ('Why is face data governance important?', 'Face authentication must be used only with formal approval, consent, retention rules, and data-protection safeguards.', 'Security');
insert into faqs (question, answer, category) values ('Justify CQI is important.', 'It creates a visible link: observed issue, decision, assigned action, evidence of implementation, review of result.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Why do we need the Dean benefits?', 'School-level oversight of programmes, evidence, attainment, CQI, audits, staff performance, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('What is the CQI workflow?', 'A concern is documented in a CQI report with context, affected programme or course, issue, proposed action, owner, target date, and required evidence. It is reviewed, implemented, evidenced, and closed only when authorised.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain academic support.', 'Provides student-support or academic-assistance workflows.', 'Features');
insert into faqs (question, answer, category) values ('What user roles interact with can raise a CQI concern?', 'A lecturer, HOP, reviewer, audit team, or Dean can identify and document a concern in a CQI report.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What benefit does reporting and export provide?', 'Data becomes useful to leadership only when it can be interpreted, reviewed, presented, and acted upon.', 'Justification');
insert into faqs (question, answer, category) values ('Define attendance bonus tracking.', 'Supports point-based recognition connected to attendance activity.', 'Features');
insert into faqs (question, answer, category) values ('What does credit transfer mean?', 'Supports credit transfer applications with transcript matching, review, justification, and decision steps.', 'Features');
insert into faqs (question, answer, category) values ('What is Supabase?', 'The backend platform providing PostgreSQL database and related application services.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the purpose of Deans see school-level data?', 'Deans need school-level information to lead academic quality across all So-CSI programmes.', 'User Roles');
insert into faqs (question, answer, category) values ('Why is secure authentication important?', 'It establishes reliable user identity and prevents unauthorised access.', 'Security');
insert into faqs (question, answer, category) values ('What is the purpose of reviewing programme and school indicators?', 'HOPs and the Dean can intervene before issues grow.', 'Procedures');
insert into faqs (question, answer, category) values ('Explain attendance bonus tracking.', 'Supports point-based recognition connected to attendance activity.', 'Features');
insert into faqs (question, answer, category) values ('What does a KPI mean?', 'Key Performance Indicator - a measurable value used to assess performance or progress.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about evidence in QMS context.', 'A document, result, record, log, or file that supports a statement or decision.', 'Terminology');
insert into faqs (question, answer, category) values ('What benefit does role-based access provide?', 'A QMS stores personal data, attendance, academic evidence, evaluations, complaints, staff records, and reports. Not all users should see all records.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the purpose of auditability?', 'Useful timestamps, status changes, responsible person details, and evidence references allow decisions to be verified.', 'Security');
insert into faqs (question, answer, category) values ('Explain the QA and CQI queue.', 'A structured view of quality or improvement items for review.', 'Features');
insert into faqs (question, answer, category) values ('Why is backups and change control important?', 'Regular backups and pre-deployment inspection enable recovery and reduce disruption when changes fail.', 'Security');
insert into faqs (question, answer, category) values ('What is the purpose of HOPs benefit?', 'Programme-level visibility, course coordination, quality follow-up, study planning, and support workflows.', 'Benefits');
insert into faqs (question, answer, category) values ('Why is centralising academic operations important?', 'It reduces duplicate work, lost files, and dependence on disconnected tools. Every record lives in one workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the data layer.', 'Supabase and PostgreSQL database tables, storage, database functions, and policies. It stores academic, user, quality, and service records.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the purpose of role-aware access?', 'It uses role-based navigation and database access controls to protect student, staff, and institutional information.', 'System Overview');
insert into faqs (question, answer, category) values ('Where is audit and compliance data stored?', 'In internal_audits and mock_audits.', 'Database');
insert into faqs (question, answer, category) values ('Why is preparing course files before teaching important?', 'Evidence processes must be ready before teaching begins.', 'Procedures');
insert into faqs (question, answer, category) values ('Define badges and certificates.', 'Records badges, student badges, and certificates.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about mock audits.', 'Supports readiness reviews before formal audit or accreditation activity.', 'Features');
insert into faqs (question, answer, category) values ('Why is reviewing programme and school indicators important?', 'HOPs and the Dean can intervene before issues grow.', 'Procedures');
insert into faqs (question, answer, category) values ('Explain how the QA and CQI queue works works.', 'It shows pending actions with status, ownership, and follow-up so nothing gets lost between meetings.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the purpose of lecturers benefit?', 'Attendance generation, evidence management, question bank, evaluation support, documents, course-file tools, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('What does least privilege mean?', 'The security principle of giving each user only the access they need.', 'Terminology');
insert into faqs (question, answer, category) values ('What is the purpose of the Dean benefits?', 'School-level oversight of programmes, evidence, attainment, CQI, audits, staff performance, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('What benefit does the Dean benefits provide?', 'School-level oversight of programmes, evidence, attainment, CQI, audits, staff performance, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('What is a study plan?', 'A structured plan showing courses across future or current academic terms.', 'Terminology');
insert into faqs (question, answer, category) values ('What is complaints management?', 'Captures, tracks, and supports resolution of complaints.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need backups and change control?', 'Regular backups and pre-deployment inspection enable recovery and reduce disruption when changes fail.', 'Security');
insert into faqs (question, answer, category) values ('What is the purpose of the objectives of QMS RISE?', 'To centralise academic operations, support So-CSI governance, improve evidence readiness, strengthen student support, support continuous improvement, improve monitoring, and provide secure role-aware access.', 'System Overview');
insert into faqs (question, answer, category) values ('Why is CQI is important important?', 'It creates a visible link: observed issue, decision, assigned action, evidence of implementation, review of result.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the student dashboard.', 'Student-focused academic shortcuts, activities, points, progress information, and notices.', 'Features');
insert into faqs (question, answer, category) values ('What does transcript and PDF OCR extraction mean?', 'Reduces manual retyping and supports faster preliminary transcript review.', 'Features');
insert into faqs (question, answer, category) values ('What is the role-aware dashboard?', 'A dashboard and navigation appropriate to the signed-in user role.', 'Features');
insert into faqs (question, answer, category) values ('Define the timetable feature.', 'Displays teaching schedule and timetable information for students, lecturers, and HOPs.', 'Features');
insert into faqs (question, answer, category) values ('Define the role-aware dashboard.', 'A dashboard and navigation appropriate to the signed-in user role.', 'Features');
insert into faqs (question, answer, category) values ('What is the presentation layer?', 'HTML, CSS, responsive UI, navigation, dashboards, cards, forms, tables, modals, and charts. It shows information and captures user actions.', 'Architecture');
insert into faqs (question, answer, category) values ('What benefit does the school to programme to course structure provide?', 'Quality responsibility needs to be visible at the appropriate level, especially within So-CSI.', 'Justification');
insert into faqs (question, answer, category) values ('What does evaluations mean?', 'Supports submission and review of evaluation-related records.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about CLO attainment.', 'Records Course Learning Outcome achievement data.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the backend platform.', 'Supabase - providing PostgreSQL database, storage, and related application services.', 'Architecture');
insert into faqs (question, answer, category) values ('What data store holds peer interaction data?', 'In peer_chat_requests, peer_chat_messages, and peer_chat_blocks.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about the attendance_logs table.', 'Stores individual attendance check-ins with student identity, subject, location, type, points, and timestamp.', 'Database');
insert into faqs (question, answer, category) values ('What does the student dashboard mean?', 'Student-focused academic shortcuts, activities, points, progress information, and notices.', 'Features');
insert into faqs (question, answer, category) values ('Justify the school to programme to course structure.', 'Quality responsibility needs to be visible at the appropriate level, especially within So-CSI.', 'Justification');
insert into faqs (question, answer, category) values ('Explain how CQI actions are closed works.', 'The record is closed only when an authorised reviewer accepts the evidence that the action has been implemented and was effective.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define lecturer evaluation.', 'Stores or supports review of lecturer evaluation data.', 'Features');
insert into faqs (question, answer, category) values ('What is peer chat?', 'Supports student chat requests, approval, rejection, messages, read status, and block controls.', 'Features');
insert into faqs (question, answer, category) values ('Justify responsive design matters.', 'Students, lecturers, and leaders access the system from phones, tablets, laptops, and desktops - the QMS must work everywhere.', 'Architecture');
insert into faqs (question, answer, category) values ('What benefit does lecturers benefit provide?', 'Attendance generation, evidence management, question bank, evaluation support, documents, course-file tools, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('What is evidence in QMS context?', 'A document, result, record, log, or file that supports a statement or decision.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about the course catalogue.', 'Stores subject code, subject name, type, study level, credit hour, prerequisites, grading method, pass criteria, status, semester, and academic year.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the Administrator role.', 'Administrators maintain authorised system and data operations: database administration tools, selected configuration, and controlled user and role administration.', 'User Roles');
insert into faqs (question, answer, category) values ('Justify active-session handling.', 'Monitoring active session identifiers helps reduce simultaneous or unauthorised account use.', 'Security');
insert into faqs (question, answer, category) values ('Why do we need reviewing programme and school indicators?', 'HOPs and the Dean can intervene before issues grow.', 'Procedures');
insert into faqs (question, answer, category) values ('What does the cqi_reports table mean?', 'Stores Continuous Quality Improvement actions with context, affected programme or course, issue description, proposed action, owner, target date, and required evidence.', 'Database');
insert into faqs (question, answer, category) values ('What is QR attendance?', 'Attendance recorded by scanning a QR code tied to an active attendance session.', 'Terminology');
insert into faqs (question, answer, category) values ('Why is Row Level Security important?', 'It enforces database-level policies that limit records available to each user.', 'Security');
insert into faqs (question, answer, category) values ('What is the purpose of confirming the academic term?', 'It ensures all records use a consistent time reference.', 'Procedures');
insert into faqs (question, answer, category) values ('Walk me through internal audits work.', 'They systematically check process effectiveness and evidence completeness to support quality review and accreditation readiness.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain the application layer.', 'The main JavaScript application, feature modules, role-aware routing, validation, and dynamic rendering. It coordinates user workflows.', 'Architecture');
insert into faqs (question, answer, category) values ('What does attendance bonus tracking mean?', 'Supports point-based recognition connected to attendance activity.', 'Features');
insert into faqs (question, answer, category) values ('Who is responsible for the system architect?', 'The system was conceived, developed, and built by R. Vinod Sarna, Dean of So-CSI and HOP for BCY and BDS.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain lecturer and staff management.', 'Maintains staff identity, school, programme, role, title, account state, and authorised permissions.', 'Features');
insert into faqs (question, answer, category) values ('What data store holds assessment engagement data?', 'In question_bank, quiz_attempts, and quiz_results.', 'Database');
insert into faqs (question, answer, category) values ('Explain UNIMY QMS RISE.', 'UNIMY QMS RISE is the University Malaysia of Computer Science & Engineering''s Quality Management System with gamification. It tracks attendance, evaluations, quizzes, and bonuses across all programmes.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify the QMS works as a continuous cycle.', 'Quality is a repeating process of Plan, Deliver, Capture Evidence, Measure, Review, Improve, and Report - not a single audit event.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain CQI reports.', 'Creates, reviews, tracks, and follows up Continuous Quality Improvement actions.', 'Features');
insert into faqs (question, answer, category) values ('What does face authentication mean?', 'Uses camera and face-related workflows where enabled and approved.', 'Features');
insert into faqs (question, answer, category) values ('Why is lecturers benefit important?', 'Attendance generation, evidence management, question bank, evaluation support, documents, course-file tools, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('Justify preparing course files before teaching.', 'Evidence processes must be ready before teaching begins.', 'Procedures');
insert into faqs (question, answer, category) values ('What database tables support feedback and staff performance data?', 'In evaluations, lecturer_evaluations, and lecturer_kpi.', 'Database');
insert into faqs (question, answer, category) values ('What does lecturer and staff management mean?', 'Maintains staff identity, school, programme, role, title, account state, and authorised permissions.', 'Features');
insert into faqs (question, answer, category) values ('Why is confirming the academic term important?', 'It ensures all records use a consistent time reference.', 'Procedures');
insert into faqs (question, answer, category) values ('Where does assessment engagement data live in the database?', 'In question_bank, quiz_attempts, and quiz_results.', 'Database');
insert into faqs (question, answer, category) values ('Which tables contain audit and compliance data?', 'In internal_audits and mock_audits.', 'Database');
insert into faqs (question, answer, category) values ('Define the clo_attainments table.', 'Stores Course Learning Outcome attainment data linking assessment evidence to intended outcomes.', 'Database');
insert into faqs (question, answer, category) values ('Who uses UNIMY QMS RISE?', 'Used by students, lecturers, Heads of Programme (HOPs), Deans, quality-assurance personnel, and administrators across So-CSI - the School of CyberSecurity and Data Intelligence.', 'System Overview');
insert into faqs (question, answer, category) values ('Define enrolment requests.', 'Captures and tracks requests related to enrolment or registration.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need verifying course catalogue details?', 'Course delivery information must be correct before students use it.', 'Procedures');
insert into faqs (question, answer, category) values ('Explain an academic term.', 'A defined teaching period, such as a semester.', 'Terminology');
insert into faqs (question, answer, category) values ('What is internal audits?', 'Records and manages internal audit activity.', 'Features');
insert into faqs (question, answer, category) values ('Justify reporting and export.', 'Data becomes useful to leadership only when it can be interpreted, reviewed, presented, and acted upon.', 'Justification');
insert into faqs (question, answer, category) values ('What does a course file mean?', 'A structured collection of evidence related to course delivery, assessment, review, and improvement.', 'Terminology');
insert into faqs (question, answer, category) values ('Walk me through CQI actions are closed.', 'The record is closed only when an authorised reviewer accepts the evidence that the action has been implemented and was effective.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about CQI reports.', 'Creates, reviews, tracks, and follows up Continuous Quality Improvement actions.', 'Features');
insert into faqs (question, answer, category) values ('Define reporting and export.', 'Produces printable, PDF-capable, and spreadsheet-compatible views.', 'Features');
insert into faqs (question, answer, category) values ('Why is document controls important?', 'Limiting document access by role and purpose protects course, staff, student, and audit evidence.', 'Security');
insert into faqs (question, answer, category) values ('What benefit does quiz, points, badges, and certificates provide?', 'Appropriate engagement features can encourage participation and recognise achievement.', 'Justification');
insert into faqs (question, answer, category) values ('What is certificate review?', 'Supports review of submitted certificate evidence, including analysis workflow.', 'Features');
insert into faqs (question, answer, category) values ('What database tables support student and staff profiles?', 'In the students and staff tables. They hold profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('Which roles have access to can raise a CQI concern?', 'A lecturer, HOP, reviewer, audit team, or Dean can identify and document a concern in a CQI report.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about RLS.', 'Row Level Security - database rules that control which database rows a user can read or change.', 'Terminology');
insert into faqs (question, answer, category) values ('What does So-CSI school and programme mapping mean?', 'Associates staff and students with So-CSI and relevant programmes.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does verifying course catalogue details provide?', 'Course delivery information must be correct before students use it.', 'Procedures');
insert into faqs (question, answer, category) values ('Who is responsible for approves CQI closure?', 'The appropriate academic authority - typically the Dean, HOP, or quality reviewer who owns the affected programme or course.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the Quiz Battle Arena.', 'Supports quiz attempts, quiz results, topics, and performance history.', 'Features');
insert into faqs (question, answer, category) values ('What does course prerequisites mean?', 'Records prerequisite requirements for courses.', 'Features');
insert into faqs (question, answer, category) values ('What is the attendance_logs table?', 'Stores individual attendance check-ins with student identity, subject, location, type, points, and timestamp.', 'Database');
insert into faqs (question, answer, category) values ('Explain the important security rule.', 'The browser application must use only safe public config values. Secret service-role keys must never appear in client-side HTML or JavaScript.', 'Security');
insert into faqs (question, answer, category) values ('What is the purpose of password protection?', 'Passwords, hashes, service-role keys, and private secrets must never be exposed in browser code.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about events and bookings.', 'Supports events, event bookings, and staff visibility of participation.', 'Features');
insert into faqs (question, answer, category) values ('Define the Lecturer role.', 'Lecturers deliver teaching, manage course-related evidence, and support students: attendance generation, course files, question bank, document tools, evaluation activity, academic support, and assigned reports.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about the Quiz Battle Arena.', 'Supports quiz attempts, quiz results, topics, and performance history.', 'Features');
insert into faqs (question, answer, category) values ('What database tables support assessment engagement data?', 'In question_bank, quiz_attempts, and quiz_results.', 'Database');
insert into faqs (question, answer, category) values ('Define questions the Dean dashboard answers.', 'Which programmes need attention? Are course files and quality evidence complete? What CLO attainment patterns need discussion? Which CQI actions remain pending? What audit observations need follow-up?', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the purpose of document controls?', 'Limiting document access by role and purpose protects course, staff, student, and audit evidence.', 'Security');
insert into faqs (question, answer, category) values ('What is RLS?', 'Row Level Security - database rules that control which database rows a user can read or change.', 'Terminology');
insert into faqs (question, answer, category) values ('What user roles interact with the system architect?', 'The system was conceived, developed, and built by R. Vinod Sarna, Dean of So-CSI and HOP for BCY and BDS.', 'System Overview');
insert into faqs (question, answer, category) values ('Which tables contain events and services data?', 'In events, event_bookings, enrolment_requests, and credit_transfers.', 'Database');
insert into faqs (question, answer, category) values ('Define the students table.', 'Stores student profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('Where does course catalogue data live in the database?', 'In the courses, course_prerequisites, and academic_terms tables.', 'Database');
insert into faqs (question, answer, category) values ('What is the deployment layer?', 'Web hosting and HTTPS deployment configuration. It delivers the QMS to users through a browser.', 'Architecture');
insert into faqs (question, answer, category) values ('Justify the Dean benefits.', 'School-level oversight of programmes, evidence, attainment, CQI, audits, staff performance, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('Explain the Quiz Battle Arena.', 'Supports quiz attempts, quiz results, topics, and performance history.', 'Features');
insert into faqs (question, answer, category) values ('What is the integration layer?', 'QR scanner, camera features, face-auth module, charts, PDF, OCR, and spreadsheet tools. It extends system functions beyond normal forms.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about QR attendance.', 'Attendance recorded by scanning a QR code tied to an active attendance session.', 'Terminology');
insert into faqs (question, answer, category) values ('Where does attendance data live in the database?', 'In attendance, attendance_sessions, and attendance_logs.', 'Database');
insert into faqs (question, answer, category) values ('Why do we need secure authentication?', 'It establishes reliable user identity and prevents unauthorised access.', 'Security');
insert into faqs (question, answer, category) values ('What data store holds documents and course evidence?', 'In documents and course_files.', 'Database');
insert into faqs (question, answer, category) values ('Define lecturer and staff management.', 'Maintains staff identity, school, programme, role, title, account state, and authorised permissions.', 'Features');
insert into faqs (question, answer, category) values ('Explain the backend platform.', 'Supabase - providing PostgreSQL database, storage, and related application services.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the faqs table.', 'Stores frequently asked questions and answers used by the self-service help and AI assistant features.', 'Database');
insert into faqs (question, answer, category) values ('What does the Student role mean?', 'Students participate in learning and manage permitted academic activities: dashboard, timetable, attendance, study plan, quizzes, documents, messages, peer chat, profile, evaluations, complaints, events, and academic support.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the purpose of preparing course files before teaching?', 'Evidence processes must be ready before teaching begins.', 'Procedures');
insert into faqs (question, answer, category) values ('Define CLO attainment.', 'Records Course Learning Outcome achievement data.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about attendance records.', 'Stores attendance events, student identity, subject, location, type, points, and timestamp.', 'Features');
insert into faqs (question, answer, category) values ('Why is verifying course catalogue details important?', 'Course delivery information must be correct before students use it.', 'Procedures');
insert into faqs (question, answer, category) values ('Explain the access and session layer.', 'Authentication, user roles, active-session controls, and Row Level Security policies. It identifies users and limits access.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the institutional hierarchy.', 'So-CSI (School) contains programmes; programmes contain courses; courses involve lecturers, students, attendance, assessments, and evidence.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the purpose of a central database?', 'Academic quality cannot be managed reliably when critical evidence is spread across personal devices, email, paper, and disconnected spreadsheets.', 'Justification');
insert into faqs (question, answer, category) values ('Define the mobile-responsive interface.', 'Uses adaptive layout, responsive grid behaviour, mobile navigation, and touch interaction.', 'Features');
insert into faqs (question, answer, category) values ('Explain Supabase.', 'The backend platform providing PostgreSQL database and related application services.', 'Terminology');
insert into faqs (question, answer, category) values ('Tell me about a CLO.', 'Course Learning Outcome - a measurable statement of what a student should achieve after a course.', 'Terminology');
insert into faqs (question, answer, category) values ('What is academic term management?', 'Defines academic terms and periods used by planning and reporting tools.', 'Features');
insert into faqs (question, answer, category) values ('Which tables contain attendance data?', 'In attendance, attendance_sessions, and attendance_logs.', 'Database');
insert into faqs (question, answer, category) values ('Explain QR attendance capture.', 'Uses mobile camera and QR capability for attendance check-in.', 'Features');
insert into faqs (question, answer, category) values ('Explain the quality cycle stages.', 'Plan, Deliver, Capture Evidence, Measure, Review, Improve, Report. Quality is a repeating process, not a single event.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the clo_attainments table?', 'Stores Course Learning Outcome attainment data linking assessment evidence to intended outcomes.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about a dashboard.', 'A visual summary of key information, indicators, status, and shortcuts.', 'Terminology');
insert into faqs (question, answer, category) values ('What does the faqs table mean?', 'Stores frequently asked questions and answers used by the self-service help and AI assistant features.', 'Database');
insert into faqs (question, answer, category) values ('What benefit does confirming the academic term provide?', 'It ensures all records use a consistent time reference.', 'Procedures');
insert into faqs (question, answer, category) values ('Tell me about evaluation reports.', 'Presents evaluation-related reports and analysis.', 'Features');
insert into faqs (question, answer, category) values ('What is the process for CQI actions are closed?', 'The record is closed only when an authorised reviewer accepts the evidence that the action has been implemented and was effective.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about live presence.', 'Supports online presence awareness for selected interaction features.', 'Features');
insert into faqs (question, answer, category) values ('What does the study plan feature mean?', 'Builds or displays planned study pathways across semesters.', 'Features');
insert into faqs (question, answer, category) values ('Define the QA and CQI queue.', 'A structured view of quality or improvement items for review.', 'Features');
insert into faqs (question, answer, category) values ('Explain enrolment requests.', 'Captures and tracks requests related to enrolment or registration.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the access and session layer.', 'Authentication, user roles, active-session controls, and Row Level Security policies. It identifies users and limits access.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about academic term management.', 'Defines academic terms and periods used by planning and reporting tools.', 'Features');
insert into faqs (question, answer, category) values ('Justify strengthening student support.', 'It provides study planning, timetable, attendance, messages, quizzes, support tools, and profile functions to help students manage their academic journey.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the purpose of role-based access?', 'A QMS stores personal data, attendance, academic evidence, evaluations, complaints, staff records, and reports. Not all users should see all records.', 'User Roles');
insert into faqs (question, answer, category) values ('What is the process for the QA and CQI queue works?', 'It shows pending actions with status, ownership, and follow-up so nothing gets lost between meetings.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about the Lecturer role.', 'Lecturers deliver teaching, manage course-related evidence, and support students: attendance generation, course files, question bank, document tools, evaluation activity, academic support, and assigned reports.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about the student dashboard.', 'Student-focused academic shortcuts, activities, points, progress information, and notices.', 'Features');
insert into faqs (question, answer, category) values ('Describe CQI actions are closed.', 'The record is closed only when an authorised reviewer accepts the evidence that the action has been implemented and was effective.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define academic term management.', 'Defines academic terms and periods used by planning and reporting tools.', 'Features');
insert into faqs (question, answer, category) values ('What is the Administrator role?', 'Administrators maintain authorised system and data operations: database administration tools, selected configuration, and controlled user and role administration.', 'User Roles');
insert into faqs (question, answer, category) values ('What benefit does reviewing programme and school indicators provide?', 'HOPs and the Dean can intervene before issues grow.', 'Procedures');
