insert into faqs (question, answer, category) values ('Explain QR attendance session creation.', 'Creates attendance sessions with code, subject, location, points, expiry, issuer, and active status.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need role-aware access?', 'It uses role-based navigation and database access controls to protect student, staff, and institutional information.', 'System Overview');
insert into faqs (question, answer, category) values ('Why is HOPs see programme-relevant data important?', 'HOPs need programme-level visibility to coordinate and monitor delivery.', 'User Roles');
