insert into faqs (question, answer, category) values ('Define complaints management.', 'Captures, tracks, and supports resolution of complaints.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does UNIMY QMS RISE provide?', 'It centralises academic quality work - attendance, evidence, evaluation, CLO attainment, CQI, audits, and reporting - replacing disconnected spreadsheets, folders, chats, and emails.', 'System Overview');
