insert into faqs (question, answer, category) values ('Tell me about an academic year.', 'The institutional year covering teaching, assessment, and reporting periods.', 'Terminology');
insert into faqs (question, answer, category) values ('What benefit does quality personnel benefit provide?', 'Access to course evidence, CLO data, CQI records, audit records, reports, and documents.', 'Benefits');
