insert into faqs (question, answer, category) values ('What is evaluation reports?', 'Presents evaluation-related reports and analysis.', 'Features');
insert into faqs (question, answer, category) values ('What does the current version mean?', 'QMS RISE - So-CSI v27.0 Web Application.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the students table.', 'Stores student profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('What database tables support study planning data?', 'In semester_plans, sp_courses, sp_semester_buckets, sp_student_courses, sp_students, and sp_timetable.', 'Database');
insert into faqs (question, answer, category) values ('What does the reporting layer mean?', 'Tables, dashboards, browser print and PDF support, and spreadsheet-capable tools. It converts records into reviewable information.', 'Architecture');
insert into faqs (question, answer, category) values ('What benefit does auditability provide?', 'Useful timestamps, status changes, responsible person details, and evidence references allow decisions to be verified.', 'Security');
insert into faqs (question, answer, category) values ('Define the backend platform.', 'Supabase - providing PostgreSQL database, storage, and related application services.', 'Architecture');
insert into faqs (question, answer, category) values ('Justify evidence readiness.', 'It supports course files, documents, attendance logs, evaluations, audits, and CQI records to create traceable evidence for review, accreditation, and decision-making.', 'System Overview');
insert into faqs (question, answer, category) values ('Why is quality personnel benefit important?', 'Access to course evidence, CLO data, CQI records, audit records, reports, and documents.', 'Benefits');
insert into faqs (question, answer, category) values ('Where does study planning data live in the database?', 'In semester_plans, sp_courses, sp_semester_buckets, sp_student_courses, sp_students, and sp_timetable.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about complaints management.', 'Captures, tracks, and supports resolution of complaints.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the CQI workflow.', 'A concern is documented in a CQI report with context, affected programme or course, issue, proposed action, owner, target date, and required evidence. It is reviewed, implemented, evidenced, and closed only when authorised.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the Lecturer role?', 'Lecturers deliver teaching, manage course-related evidence, and support students: attendance generation, course files, question bank, document tools, evaluation activity, academic support, and assigned reports.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain questions the Dean dashboard answers.', 'Which programmes need attention? Are course files and quality evidence complete? What CLO attainment patterns need discussion? Which CQI actions remain pending? What audit observations need follow-up?', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the lecturer KPI tracker.', 'Tracks approved lecturer Key Performance Indicators.', 'Features');
insert into faqs (question, answer, category) values ('Explain credit transfer.', 'Supports credit transfer applications with transcript matching, review, justification, and decision steps.', 'Features');
insert into faqs (question, answer, category) values ('What does the attendance_sessions table mean?', 'Stores controlled attendance events with a code, subject, location, points, expiry, issuer, and active status.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about questions the Dean dashboard answers.', 'Which programmes need attention? Are course files and quality evidence complete? What CLO attainment patterns need discussion? Which CQI actions remain pending? What audit observations need follow-up?', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What benefit does continuous improvement provide?', 'It records quality observations and CQI follow-up activity to ensure identified issues lead to accountable action.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify mobile-responsive design.', 'QMS access must work where users are, including on phones used for attendance and quick academic checks.', 'Justification');
insert into faqs (question, answer, category) values ('Explain the HOP role.', 'Heads of Programme coordinate programme delivery and quality: programme monitoring, academic support, reports, review of course and evidence activity, study-plan support, and approved quality workflows.', 'User Roles');
insert into faqs (question, answer, category) values ('What does Supabase mean?', 'The backend platform providing PostgreSQL database and related application services.', 'Terminology');
insert into faqs (question, answer, category) values ('Where is documents and course evidence stored?', 'In documents and course_files.', 'Database');
insert into faqs (question, answer, category) values ('What does academic term management mean?', 'Defines academic terms and periods used by planning and reporting tools.', 'Features');
insert into faqs (question, answer, category) values ('What is the Staff role?', 'Staff carry out assigned operational or support work. Access varies by assigned role and approved permission.', 'User Roles');
insert into faqs (question, answer, category) values ('Justify security and RLS.', 'Personal, academic, and institutional data requires access controls at both interface and database levels.', 'Justification');
insert into faqs (question, answer, category) values ('Explain live presence.', 'Supports online presence awareness for selected interaction features.', 'Features');
insert into faqs (question, answer, category) values ('What does the Administrator role mean?', 'Administrators maintain authorised system and data operations: database administration tools, selected configuration, and controlled user and role administration.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain RLS.', 'Row Level Security - database rules that control which database rows a user can read or change.', 'Terminology');
insert into faqs (question, answer, category) values ('What benefit does students benefit provide?', 'Timetable access, attendance visibility, study planning, quizzes, messages, peer support, documents, events, recognition, and support tools.', 'Benefits');
insert into faqs (question, answer, category) values ('Explain the Dean role.', 'The Dean leads academic quality for So-CSI: school and programme monitoring, quality review, CQI oversight, audit visibility, staff and lecturer review, and strategic reporting.', 'User Roles');
insert into faqs (question, answer, category) values ('What is events and bookings?', 'Supports events, event bookings, and staff visibility of participation.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need the school to programme to course structure?', 'Quality responsibility needs to be visible at the appropriate level, especially within So-CSI.', 'Justification');
insert into faqs (question, answer, category) values ('Why is the QMS works as a continuous cycle important?', 'Quality is a repeating process of Plan, Deliver, Capture Evidence, Measure, Review, Improve, and Report - not a single audit event.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the integration layer.', 'QR scanner, camera features, face-auth module, charts, PDF, OCR, and spreadsheet tools. It extends system functions beyond normal forms.', 'Architecture');
insert into faqs (question, answer, category) values ('Define the data layer.', 'Supabase and PostgreSQL database tables, storage, database functions, and policies. It stores academic, user, quality, and service records.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the purpose of CQI is important?', 'It creates a visible link: observed issue, decision, assigned action, evidence of implementation, review of result.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Explain the AI assistant interface.', 'Provides an AI-assistant entry point where configured.', 'Features');
insert into faqs (question, answer, category) values ('What is attendance bonus tracking?', 'Supports point-based recognition connected to attendance activity.', 'Features');
insert into faqs (question, answer, category) values ('What does the access and session layer mean?', 'Authentication, user roles, active-session controls, and Row Level Security policies. It identifies users and limits access.', 'Architecture');
insert into faqs (question, answer, category) values ('What is the current version?', 'QMS RISE - So-CSI v27.0 Web Application.', 'System Overview');
insert into faqs (question, answer, category) values ('Define a study plan.', 'A structured plan showing courses across future or current academic terms.', 'Terminology');
insert into faqs (question, answer, category) values ('Explain CQI.', 'Continuous Quality Improvement - a formal process for identifying issues, taking action, and checking results.', 'Terminology');
insert into faqs (question, answer, category) values ('Define live presence.', 'Supports online presence awareness for selected interaction features.', 'Features');
insert into faqs (question, answer, category) values ('Explain the Lecturer role.', 'Lecturers deliver teaching, manage course-related evidence, and support students: attendance generation, course files, question bank, document tools, evaluation activity, academic support, and assigned reports.', 'User Roles');
insert into faqs (question, answer, category) values ('Explain mock audits.', 'Supports readiness reviews before formal audit or accreditation activity.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about QR attendance capture.', 'Uses mobile camera and QR capability for attendance check-in.', 'Features');
insert into faqs (question, answer, category) values ('What does questions the Dean dashboard answers mean?', 'Which programmes need attention? Are course files and quality evidence complete? What CLO attainment patterns need discussion? Which CQI actions remain pending? What audit observations need follow-up?', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What is the AI assistant interface?', 'Provides an AI-assistant entry point where configured.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does strengthening student support provide?', 'It provides study planning, timetable, attendance, messages, quizzes, support tools, and profile functions to help students manage their academic journey.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain secure login.', 'Student and staff login, session handling, logout, active-device session controls, and password workflows. It confirms identity before showing protected information.', 'Features');
insert into faqs (question, answer, category) values ('Why do we need Deans see school-level data?', 'Deans need school-level information to lead academic quality across all So-CSI programmes.', 'User Roles');
insert into faqs (question, answer, category) values ('Tell me about reporting and export.', 'Produces printable, PDF-capable, and spreadsheet-compatible views.', 'Features');
insert into faqs (question, answer, category) values ('Define CQI reports.', 'Creates, reviews, tracks, and follows up Continuous Quality Improvement actions.', 'Features');
insert into faqs (question, answer, category) values ('What does document management mean?', 'Uploads, retrieves, organises, and reviews documents.', 'Features');
insert into faqs (question, answer, category) values ('Define the platform type.', 'A responsive, web-based Quality Management System accessible from desktop and mobile browsers.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the important security rule.', 'The browser application must use only safe public config values. Secret service-role keys must never appear in client-side HTML or JavaScript.', 'Security');
insert into faqs (question, answer, category) values ('Define QR attendance capture.', 'Uses mobile camera and QR capability for attendance check-in.', 'Features');
insert into faqs (question, answer, category) values ('What does the lecturer KPI tracker mean?', 'Tracks approved lecturer Key Performance Indicators.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about FAQ and self-service help.', 'Provides frequently asked questions and guided support information for all users.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does centralising academic operations provide?', 'It reduces duplicate work, lost files, and dependence on disconnected tools. Every record lives in one workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Why do we need UNIMY QMS RISE?', 'It centralises academic quality work - attendance, evidence, evaluation, CLO attainment, CQI, audits, and reporting - replacing disconnected spreadsheets, folders, chats, and emails.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain reporting and export.', 'Produces printable, PDF-capable, and spreadsheet-compatible views.', 'Features');
insert into faqs (question, answer, category) values ('What does secure login mean?', 'Student and staff login, session handling, logout, active-device session controls, and password workflows. It confirms identity before showing protected information.', 'Features');
insert into faqs (question, answer, category) values ('Where does student and staff profiles live in the database?', 'In the students and staff tables. They hold profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('Which tables contain recognition and achievement data?', 'In rise_points, badges, student_badges, and certificates.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about document management.', 'Uploads, retrieves, organises, and reviews documents.', 'Features');
insert into faqs (question, answer, category) values ('Where is recognition and achievement data stored?', 'In rise_points, badges, student_badges, and certificates.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about the AI assistant interface.', 'Provides an AI-assistant entry point where configured.', 'Features');
insert into faqs (question, answer, category) values ('Justify verifying course catalogue details.', 'Course delivery information must be correct before students use it.', 'Procedures');
insert into faqs (question, answer, category) values ('What user roles interact with approves CQI closure?', 'The appropriate academic authority - typically the Dean, HOP, or quality reviewer who owns the affected programme or course.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('What data store holds student and staff profiles?', 'In the students and staff tables. They hold profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('What is a CLO?', 'Course Learning Outcome - a measurable statement of what a student should achieve after a course.', 'Terminology');
insert into faqs (question, answer, category) values ('Where is student and staff profiles stored?', 'In the students and staff tables. They hold profile, role, programme and school context, active status, and session-related fields.', 'Database');
insert into faqs (question, answer, category) values ('Why is role-based access important?', 'A QMS stores personal data, attendance, academic evidence, evaluations, complaints, staff records, and reports. Not all users should see all records.', 'User Roles');
insert into faqs (question, answer, category) values ('What is RISE points and tiers?', 'Allocates and calculates points across attendance, evaluation, quizzes, bonuses, streaks, workshops, competitions, and Coursera activity.', 'Features');
insert into faqs (question, answer, category) values ('Where does documents and course evidence live in the database?', 'In documents and course_files.', 'Database');
insert into faqs (question, answer, category) values ('Tell me about the start-of-semester checklist.', 'Confirm academic term and year, verify course catalogue, confirm staff role and student status, review timetable, prepare course files, and test login and role-specific navigation.', 'Procedures');
insert into faqs (question, answer, category) values ('Define the deployment layer.', 'Web hosting and HTTPS deployment configuration. It delivers the QMS to users through a browser.', 'Architecture');
insert into faqs (question, answer, category) values ('Tell me about the mobile-responsive interface.', 'Uses adaptive layout, responsive grid behaviour, mobile navigation, and touch interaction.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about QS1 papers.', 'Supports records connected to quality-system or assessment-paper processes.', 'Features');
insert into faqs (question, answer, category) values ('Justify least privilege.', 'Giving only the minimum access necessary limits damage from mistakes or compromised accounts.', 'Security');
insert into faqs (question, answer, category) values ('Define a CLO.', 'Course Learning Outcome - a measurable statement of what a student should achieve after a course.', 'Terminology');
insert into faqs (question, answer, category) values ('Define messages.', 'Supports internal messages and communication.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about the platform type.', 'A responsive, web-based Quality Management System accessible from desktop and mobile browsers.', 'System Overview');
insert into faqs (question, answer, category) values ('Justify the objectives of QMS RISE.', 'To centralise academic operations, support So-CSI governance, improve evidence readiness, strengthen student support, support continuous improvement, improve monitoring, and provide secure role-aware access.', 'System Overview');
insert into faqs (question, answer, category) values ('What is the attendance_sessions table?', 'Stores controlled attendance events with a code, subject, location, points, expiry, issuer, and active status.', 'Database');
insert into faqs (question, answer, category) values ('Explain the question bank.', 'Maintains reusable assessment questions and related course information.', 'Features');
insert into faqs (question, answer, category) values ('What does the end-of-semester checklist mean?', 'Record or validate CLO attainment, review evaluation and performance indicators, review course files and audit readiness, create CQI reports, collect evidence, generate reports, and carry approved improvements into the next cycle.', 'Procedures');
insert into faqs (question, answer, category) values ('What does the attendance_logs table mean?', 'Stores individual attendance check-ins with student identity, subject, location, type, points, and timestamp.', 'Database');
insert into faqs (question, answer, category) values ('Define user profile management.', 'View and update permitted personal data, profile avatar, account details, and preferences.', 'Features');
insert into faqs (question, answer, category) values ('Justify lecturers benefit.', 'Attendance generation, evidence management, question bank, evaluation support, documents, course-file tools, and reports.', 'Benefits');
insert into faqs (question, answer, category) values ('Tell me about the institutional hierarchy.', 'So-CSI (School) contains programmes; programmes contain courses; courses involve lecturers, students, attendance, assessments, and evidence.', 'System Overview');
insert into faqs (question, answer, category) values ('Explain face authentication.', 'Uses camera and face-related workflows where enabled and approved.', 'Features');
insert into faqs (question, answer, category) values ('Define an audit trail.', 'A traceable record of actions, dates, decisions, and responsible people.', 'Terminology');
insert into faqs (question, answer, category) values ('Define evaluation reports.', 'Presents evaluation-related reports and analysis.', 'Features');
insert into faqs (question, answer, category) values ('Tell me about user profile management.', 'View and update permitted personal data, profile avatar, account details, and preferences.', 'Features');
insert into faqs (question, answer, category) values ('What is the purpose of face data governance?', 'Face authentication must be used only with formal approval, consent, retention rules, and data-protection safeguards.', 'Security');
insert into faqs (question, answer, category) values ('Define secure login.', 'Student and staff login, session handling, logout, active-device session controls, and password workflows. It confirms identity before showing protected information.', 'Features');
insert into faqs (question, answer, category) values ('Explain the mobile-responsive interface.', 'Uses adaptive layout, responsive grid behaviour, mobile navigation, and touch interaction.', 'Features');
insert into faqs (question, answer, category) values ('Explain how to validate mobile workflows works.', 'Test all major workflows on a phone after UI changes, especially navigation, modals, forms, tables, camera use, and document uploads.', 'Security');
insert into faqs (question, answer, category) values ('What does the application layer mean?', 'The main JavaScript application, feature modules, role-aware routing, validation, and dynamic rendering. It coordinates user workflows.', 'Architecture');
insert into faqs (question, answer, category) values ('Who can see approves CQI closure?', 'The appropriate academic authority - typically the Dean, HOP, or quality reviewer who owns the affected programme or course.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define FAQ and self-service help.', 'Provides frequently asked questions and guided support information for all users.', 'Features');
insert into faqs (question, answer, category) values ('What does an audit trail mean?', 'A traceable record of actions, dates, decisions, and responsible people.', 'Terminology');
insert into faqs (question, answer, category) values ('Where is course catalogue data stored?', 'In the courses, course_prerequisites, and academic_terms tables.', 'Database');
insert into faqs (question, answer, category) values ('Define the vision of QMS RISE.', 'To make academic quality work visible, structured, traceable, and easier to improve through a common workspace.', 'System Overview');
insert into faqs (question, answer, category) values ('Tell me about the quality cycle stages.', 'Plan, Deliver, Capture Evidence, Measure, Review, Improve, Report. Quality is a repeating process, not a single event.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define the Dean role.', 'The Dean leads academic quality for So-CSI: school and programme monitoring, quality review, CQI oversight, audit visibility, staff and lecturer review, and strategic reporting.', 'User Roles');
insert into faqs (question, answer, category) values ('What does RISE points and tiers mean?', 'Allocates and calculates points across attendance, evaluation, quizzes, bonuses, streaks, workshops, competitions, and Coursera activity.', 'Features');
insert into faqs (question, answer, category) values ('Define events and bookings.', 'Supports events, event bookings, and staff visibility of participation.', 'Features');
insert into faqs (question, answer, category) values ('What benefit does responsive design matters provide?', 'Students, lecturers, and leaders access the system from phones, tablets, laptops, and desktops - the QMS must work everywhere.', 'Architecture');
insert into faqs (question, answer, category) values ('What benefit does Row Level Security provide?', 'It enforces database-level policies that limit records available to each user.', 'Security');
insert into faqs (question, answer, category) values ('What is the faqs table?', 'Stores frequently asked questions and answers used by the self-service help and AI assistant features.', 'Database');
insert into faqs (question, answer, category) values ('Define the integration layer.', 'QR scanner, camera features, face-auth module, charts, PDF, OCR, and spreadsheet tools. It extends system functions beyond normal forms.', 'Architecture');
insert into faqs (question, answer, category) values ('What does user profile management mean?', 'View and update permitted personal data, profile avatar, account details, and preferences.', 'Features');
insert into faqs (question, answer, category) values ('What is the start-of-semester checklist?', 'Confirm academic term and year, verify course catalogue, confirm staff role and student status, review timetable, prepare course files, and test login and role-specific navigation.', 'Procedures');
insert into faqs (question, answer, category) values ('Why is quiz, points, badges, and certificates important?', 'Appropriate engagement features can encourage participation and recognise achievement.', 'Justification');
insert into faqs (question, answer, category) values ('Why is HOPs benefit important?', 'Programme-level visibility, course coordination, quality follow-up, study planning, and support workflows.', 'Benefits');
insert into faqs (question, answer, category) values ('Explain an audit trail.', 'A traceable record of actions, dates, decisions, and responsible people.', 'Terminology');
insert into faqs (question, answer, category) values ('What is evaluations?', 'Supports submission and review of evaluation-related records.', 'Features');
insert into faqs (question, answer, category) values ('Walk me through the QA and CQI queue works.', 'It shows pending actions with status, ownership, and follow-up so nothing gets lost between meetings.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Define a KPI.', 'Key Performance Indicator - a measurable value used to assess performance or progress.', 'Terminology');
insert into faqs (question, answer, category) values ('How does the QA and CQI queue works work?', 'It shows pending actions with status, ownership, and follow-up so nothing gets lost between meetings.', 'Quality Workflow');
insert into faqs (question, answer, category) values ('Tell me about the current version.', 'QMS RISE - So-CSI v27.0 Web Application.', 'System Overview');
insert into faqs (question, answer, category) values ('Which tables contain peer interaction data?', 'In peer_chat_requests, peer_chat_messages, and peer_chat_blocks.', 'Database');
insert into faqs (question, answer, category) values ('Define an academic term.', 'A defined teaching period, such as a semester.', 'Terminology');
insert into faqs (question, answer, category) values ('Where is feedback and staff performance data stored?', 'In evaluations, lecturer_evaluations, and lecturer_kpi.', 'Database');
insert into faqs (question, answer, category) values ('Explain a HOP.', 'Head of Programme - the person coordinating programme-level academic delivery and quality.', 'Terminology');
insert into faqs (question, answer, category) values ('Why is a central database important?', 'Academic quality cannot be managed reliably when critical evidence is spread across personal devices, email, paper, and disconnected spreadsheets.', 'Justification');
insert into faqs (question, answer, category) values ('Why do we need least privilege?', 'Giving only the minimum access necessary limits damage from mistakes or compromised accounts.', 'Security');
insert into faqs (question, answer, category) values ('Tell me about the during-semester checklist.', 'Create attendance sessions, review attendance patterns, maintain course files, use quizzes and support tools, record quality concerns, and review programme indicators.', 'Procedures');